   size_t b = utf16_to_byte(s, ARG(0).i < 0 ? 0 : ARG(0).i);
   size_t e = nargs >= 2 ? utf16_to_byte(s, args[1].i < 0 ? 0 : args[1].i) : len;
   if (b > len) b = len;
   if (e > len) e = len;
   if (b > e) b = e;
   RETL(dvm_new_string_n(vm, s + b, e - b));
