/* java.util.regex backed by the host's POSIX ERE engine.  AndroidX uses this
 * during VM capability detection, and application glue uses the same small
 * API surface for validation. */
struct rt_regex_pattern {
   regex_t re;
   int valid;
   char *expression;
   /* POSIX ERE has no non-capturing group, so (?:...) is emitted as an
    * ordinary host group.  Preserve Java's public group numbering by mapping
    * each Java capture to the corresponding host capture. */
   uint8_t group_map[16];
};
struct rt_regex_matcher {
   struct rt_regex_pattern *pattern;
   char *input;
   regmatch_t groups[16];
   int matched;
};

/* Java's predefined and Unicode-property character classes, as POSIX bracket
 * expressions.  The `inner` form is what goes *inside* an existing [...]; the
 * `outer` form is the whole class.
 *
 * The host engine works on bytes in the C locale, so a Unicode general
 * category can only be approximated — but the approximation is exact for the
 * thing these are used for.  \p{C} ("other": control, format, surrogate,
 * private use, unassigned) is how AppsFlyer strips non-printing characters
 * from its JSON payload with replaceAll("\\p{C}", ""), and over UTF-8 bytes
 * [:cntrl:] matches exactly the ASCII control bytes and leaves every
 * continuation byte of a multi-byte character alone, which is the intent.
 * The alternative — refusing the pattern — is what this replaces, and it was
 * not neutral: the SDK caught the PatternSyntaxException, failed to prepare
 * the event, and retried, throwing eighteen hundred exceptions a second
 * through the whole Cross Worlds loading screen. */
struct regex_class_map { const char *name; const char *inner; };
static const struct regex_class_map kRegexClasses[] = {
   /* POSIX classes Java spells the same way */
   { "Lower",  "[:lower:]"  }, { "Upper",  "[:upper:]"  },
   { "Alpha",  "[:alpha:]"  }, { "Digit",  "[:digit:]"  },
   { "Alnum",  "[:alnum:]"  }, { "Punct",  "[:punct:]"  },
   { "Graph",  "[:graph:]"  }, { "Print",  "[:print:]"  },
   { "Blank",  "[:blank:]"  }, { "Cntrl",  "[:cntrl:]"  },
   { "XDigit", "[:xdigit:]" }, { "Space",  "[:space:]"  },
   { "ASCII",  "\\x00-\\x7f" },
   /* Unicode general categories, one- and two-letter forms */
   { "L",  "[:alpha:]" }, { "Lu", "[:upper:]" }, { "Ll", "[:lower:]" },
   { "Lt", "[:upper:]" }, { "Lm", "[:alpha:]" }, { "Lo", "[:alpha:]" },
   { "N",  "[:digit:]" }, { "Nd", "[:digit:]" }, { "Nl", "[:digit:]" },
   { "No", "[:digit:]" },
   { "P",  "[:punct:]" }, { "S",  "[:punct:]" },
   { "Z",  "[:space:]" }, { "Zs", "[:space:]" },
   { "C",  "[:cntrl:]" }, { "Cc", "[:cntrl:]" }, { "Cf", "[:cntrl:]" },
   { "Cn", "[:cntrl:]" }, { "Co", "[:cntrl:]" }, { "Cs", "[:cntrl:]" },
};

static const char *regex_class_body(const char *name, size_t len)
{
   for (size_t i = 0; i < sizeof kRegexClasses / sizeof kRegexClasses[0]; ++i)
      if (strlen(kRegexClasses[i].name) == len &&
          !strncmp(kRegexClasses[i].name, name, len))
         return kRegexClasses[i].inner;
   return NULL;
}

static char *regex_java_to_ere(const char *src, struct rt_regex_pattern *meta)
{
   if (!src) return NULL;
   size_t n = strlen(src), cap = n * 16 + 1, j = 0;
   char *dst = malloc(cap);
   if (!dst) return NULL;
   bool in_class = false;
   unsigned host_group = 0, java_group = 0;
   if (meta) meta->group_map[0] = 0;

#define EMIT(str) do { const char *s_ = (str); size_t m_ = strlen(s_); \
                       memcpy(dst + j, s_, m_); j += m_; } while (0)

   for (size_t i = 0; i < n; ++i) {
      if (src[i] == '\\' && i + 1 < n) {
         const char esc = src[i + 1];
         const char *body = NULL;
         bool negate = false;
         size_t consumed = 1;          /* the escape letter itself */

         switch (esc) {
            case 'd': body = "[:digit:]"; break;
            case 'D': body = "[:digit:]"; negate = true; break;
            case 's': body = "[:space:]"; break;
            case 'S': body = "[:space:]"; negate = true; break;
            case 'w': body = "[:alnum:]_"; break;
            case 'W': body = "[:alnum:]_"; negate = true; break;
            case 'p': case 'P': {
               negate = (esc == 'P');
               const char *name = src + i + 2;
               size_t len = 0;
               if (*name == '{') {
                  ++name;
                  while (name[len] && name[len] != '}') ++len;
                  if (name[len] != '}') break;      /* unterminated: literal */
                  consumed = 1 + 1 + len + 1;       /* p + { + name + } */
               } else if (*name) {
                  len = 1;                          /* \pL, the one-letter form */
                  consumed = 2;
               } else {
                  break;
               }
               /* Java allows an "Is" or "In" prefix (IsAlpha, InGreek). */
               if (len > 2 && (!strncmp(name, "Is", 2) || !strncmp(name, "In", 2))) {
                  const char *b = regex_class_body(name + 2, len - 2);
                  if (b) { body = b; break; }
               }
               body = regex_class_body(name, len);
               break;
            }
            default: break;
         }

         if (body) {
            if (in_class) {
               /* Inside an existing class only the body can be spliced in; a
                * negated property there would need a set difference the host
                * engine does not have, so it is left to match nothing extra. */
               if (!negate) EMIT(body);
            } else {
               EMIT(negate ? "[^" : "[");
               EMIT(body);
               EMIT("]");
            }
            i += consumed;
            continue;
         }
         /* Not a class escape: hand both characters to the host engine. */
         dst[j++] = src[i];
         dst[j++] = src[i + 1];
         ++i;
         continue;
      }

      if (src[i] == '(' && !in_class) {
         ++host_group;
         if (i + 2 < n && src[i + 1] == '?' && src[i + 2] == ':') {
            /* ERE captures it internally; group_map hides that extra group
             * from Matcher.group() and replacement $n references. */
            dst[j++] = '(';
            i += 2;
         } else {
            ++java_group;
            if (meta && java_group < sizeof meta->group_map)
               meta->group_map[java_group] =
                  host_group < UINT8_MAX ? (uint8_t)host_group : UINT8_MAX;
            dst[j++] = src[i];
         }
      } else if (src[i] == '[') {
         in_class = true;
         dst[j++] = src[i];
      } else if (src[i] == ']' && in_class) {
         in_class = false;
         dst[j++] = src[i];
      } else if (src[i] == '-' && in_class) {
         /* Java treats '-' as a literal when it cannot form a valid range.
          * glibc's POSIX ERE rejects e.g. [0-9-_.], interpreting 9-_ as a
          * descending range.  Preserve ordinary ASCII ranges but quote every
          * other mid-class dash for the host engine.
          *
          * Do NOT escape a leading '-' (right after '[' or '[^'): POSIX already
          * treats that as a literal, and writing [\-._ turns into a bad range
          * from '\\' to '.' ("Invalid range end").  That broke Facebook PKCE
          * (^[-._~A-Za-z0-9]+$) and aborted ConnectToChannel on the title tap. */
         unsigned char prev = i ? (unsigned char)src[i - 1] : 0;
         unsigned char next = i + 1 < n ? (unsigned char)src[i + 1] : 0;
         bool at_start = (prev == '[') ||
             (prev == '^' && i >= 2 && src[i - 2] == '[');
         bool range = !at_start && isalnum(prev) && isalnum(next) && prev <= next;
         if (!range && !at_start) dst[j++] = '\\';
         dst[j++] = '-';
      } else {
         dst[j++] = src[i];
      }
   }
#undef EMIT
   dst[j] = '\0';
   return dst;
}

static bool regex_compile(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *java = dvm_string_utf8(vm, ARG(0).l);
   struct rt_regex_pattern *p = calloc(1, sizeof *p);
   char *ere = regex_java_to_ere(java, p);
   struct dvm_class *c = dvm__class_by_desc(vm, "Ljava/util/regex/Pattern;");
   dvm_ref ref = (p && c) ? dvm_new_object(vm, c) : 0;
   if (!ere || !p || !ref || regcomp(&p->re, ere, REG_EXTENDED) != 0) {
      free(ere); free(p);
      dvm__throw(vm, "java/util/regex/PatternSyntaxException", "%s",
                 java ? java : "null");
      return false;
   }
   free(ere);
   p->valid = 1;
   p->expression = strdup(java);
   dvm__obj(vm, ref)->data = p;
   RETL(ref);
}

static int regex_exec(const struct rt_regex_pattern *pattern,
                      const char *input, regmatch_t groups[16])
{
   regmatch_t host[64];
   int rc = regexec(&pattern->re, input, sizeof host / sizeof host[0], host, 0);
   if (rc != 0) return rc;
   groups[0] = host[0];
   for (size_t i = 1; i < 16; ++i) {
      uint8_t mapped = pattern->group_map[i];
      groups[i] = mapped && mapped < sizeof host / sizeof host[0]
         ? host[mapped] : (regmatch_t){ .rm_so = -1, .rm_eo = -1 };
   }
   return 0;
}

static bool regex_matcher(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   (void)nargs;
   struct dvm_class *c = dvm__class_by_desc(vm, "Ljava/util/regex/Matcher;");
   dvm_ref ref = c ? dvm_new_object(vm, c) : 0;
   struct rt_regex_matcher *m = calloc(1, sizeof *m);
   const char *input = dvm_string_utf8(vm, ARG(0).l);
   if (!ref || !m || !input) { free(m); RETL(0); }
   m->pattern = dvm__obj(vm, self) ? dvm__obj(vm, self)->data : NULL;
   m->input = strdup(input);
   if (!m->input) { free(m); RETL(0); }
   dvm__obj(vm, ref)->data = m;
   RETL(ref);
}

static bool regex_matches(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_regex_matcher *m = o ? o->data : NULL;
   if (!m || !m->pattern || !m->pattern->valid || !m->input) RETI(0);
   m->matched = regex_exec(m->pattern, m->input, m->groups) == 0;
   if (m->matched && (m->groups[0].rm_so != 0 ||
       (size_t)m->groups[0].rm_eo != strlen(m->input))) m->matched = 0;
   RETI(m->matched);
}

static bool regex_group(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_regex_matcher *m = o ? o->data : NULL;
   int idx = nargs > 0 ? ARG(0).i : 0;
   if (!m || !m->matched || idx < 0 || idx >= 16 ||
       m->groups[idx].rm_so < 0) RETL(0);
   size_t n = (size_t)(m->groups[idx].rm_eo - m->groups[idx].rm_so);
   char *s = malloc(n + 1);
   if (!s) RETL(0);
   memcpy(s, m->input + m->groups[idx].rm_so, n); s[n] = '\0';
   dvm_ref ref = dvm_new_string(vm, s);
   free(s);
   RETL(ref);
}

static dvm_ref regex_replace_text(struct dvm *vm,
                                  struct rt_regex_pattern *pattern,
                                  const char *input, const char *replacement,
                                  bool first_only)
{
   if (!pattern || !pattern->valid || !input || !replacement) return 0;
   struct rt_bytes b = { 0 };
   const char *cur = input;
   regmatch_t groups[16];
   while (regex_exec(pattern, cur, groups) == 0 && groups[0].rm_so >= 0) {
      bytes_append(&b, cur, (size_t)groups[0].rm_so);
      for (const char *r = replacement; *r; ++r) {
         if (*r == '\\' && r[1]) { bytes_append(&b, ++r, 1); continue; }
         if (*r == '$' && r[1] >= '0' && r[1] <= '9') {
            int g = *++r - '0';
            if (groups[g].rm_so >= 0)
               bytes_append(&b, cur + groups[g].rm_so,
                            (size_t)(groups[g].rm_eo - groups[g].rm_so));
            continue;
         }
         bytes_append(&b, r, 1);
      }
      size_t used = (size_t)groups[0].rm_eo;
      if (!used) { if (*cur) bytes_append(&b, cur, 1); used = *cur ? 1 : 0; }
      cur += used;
      if (first_only) break;
      if (!used) break;
   }
   bytes_append(&b, cur, strlen(cur));
   dvm_ref result = dvm_new_string_n(vm, b.p ? (char *)b.p : "", b.len);
   free(b.p);
   return result;
}

static bool regex_replaceAll(struct dvm *vm, dvm_ref self,
                             const union dvm_value *args, int nargs,
                             union dvm_value *out)
{
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_regex_matcher *m = o ? o->data : NULL;
   const char *replacement = nargs ? dvm_string_utf8(vm, ARG(0).l) : NULL;
   RETL(m ? regex_replace_text(vm, m->pattern, m->input, replacement, false) : 0);
}

static bool regex_quote(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *s = dvm_string_utf8(vm, ARG(0).l);
   if (!s) RETL(0);
   struct rt_bytes b = { 0 };
   for (const char *p = s; *p; ++p) {
      if (strchr(".[]{}()*+?^$|\\", *p)) bytes_append(&b, "\\", 1);
      bytes_append(&b, p, 1);
   }
   dvm_ref result = dvm_new_string_n(vm, b.p ? (char *)b.p : "", b.len);
   free(b.p);
   RETL(result);
}

static bool s_replaceAll(struct dvm *vm, dvm_ref self,
                         const union dvm_value *args, int nargs,
                         union dvm_value *out)
{
   const char *expr = dvm_string_utf8(vm, ARG(0).l);
   const char *replacement = nargs > 1 ? dvm_string_utf8(vm, ARG(1).l) : NULL;
   struct rt_regex_pattern pattern = { 0 };
   char *ere = regex_java_to_ere(expr, &pattern);
   if (!ere || regcomp(&pattern.re, ere, REG_EXTENDED) != 0) {
      free(ere);
      dvm__throw(vm, "java/util/regex/PatternSyntaxException", "%s", expr ? expr : "null");
      return false;
   }
   free(ere); pattern.valid = 1;
   dvm_ref result = regex_replace_text(vm, &pattern, sref(vm, self), replacement,
                                       false);
   regfree(&pattern.re);
   RETL(result);
}

static bool s_replaceFirst(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   const char *expr = nargs > 0 ? dvm_string_utf8(vm, ARG(0).l) : NULL;
   const char *replacement = nargs > 1 ? dvm_string_utf8(vm, ARG(1).l) : NULL;
   struct rt_regex_pattern pattern = { 0 };
   char *ere = regex_java_to_ere(expr, &pattern);
   if (!ere || regcomp(&pattern.re, ere, REG_EXTENDED) != 0) {
      free(ere);
      dvm__throw(vm, "java/util/regex/PatternSyntaxException", "%s",
                 expr ? expr : "null");
      return false;
   }
   free(ere);
   pattern.valid = 1;
   dvm_ref result = regex_replace_text(vm, &pattern, sref(vm, self), replacement,
                                       true);
   regfree(&pattern.re);
   RETL(result);
}

struct rt_tokenizer { char *text, *delims; size_t pos; };

static bool tokenizer_init(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   const char *text = nargs > 0 ? dvm_string_utf8(vm, ARG(0).l) : "";
   const char *delims = nargs > 1 ? dvm_string_utf8(vm, ARG(1).l) : " \t\n\r\f";
   struct rt_tokenizer *t = calloc(1, sizeof *t);
   if (t) {
      t->text = strdup(text ? text : "");
      t->delims = strdup(delims ? delims : "");
      dvm__obj(vm, self)->data = t;
   }
   RETV();
}

static void tokenizer_skip(struct rt_tokenizer *t)
{
   if (!t || !t->text || !t->delims) return;
   while (t->text[t->pos] && strchr(t->delims, t->text[t->pos])) ++t->pos;
}

static bool tokenizer_has_more(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_tokenizer *t = o ? o->data : NULL;
   tokenizer_skip(t);
   RETI(t && t->text && t->text[t->pos]);
}

static bool tokenizer_next(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_tokenizer *t = o ? o->data : NULL;
   tokenizer_skip(t);
   if (!t || !t->text || !t->text[t->pos]) {
      dvm__throw(vm, "java/util/NoSuchElementException", "StringTokenizer");
      return false;
   }
   size_t start = t->pos;
   while (t->text[t->pos] && !strchr(t->delims, t->text[t->pos])) ++t->pos;
   RETL(dvm_new_string_n(vm, t->text + start, t->pos - start));
}

/* ------------------------------------------------------------------------ *
 * java.io.PrintStream — System.out / System.err
 * ------------------------------------------------------------------------ */

static bool ps_println(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   (void)self; (void)out;
   if (nargs < 1) { fprintf(stderr, "[dvm:out]\n"); RETV(); }
   const char *s = dvm_string_utf8(vm, ARG(0).l);
   if (s) fprintf(stderr, "[dvm:out] %s\n", s);
   else fprintf(stderr, "[dvm:out] %d\n", ARG(0).i);
   RETV();
}

/* ------------------------------------------------------------------------ *
 * java.lang.Class
 * ------------------------------------------------------------------------ */

static dvm_ref class_object_for(struct dvm *vm, struct dvm_class *cls)
{
   if (!cls) return 0;
   if (cls->class_object) return cls->class_object;
   dvm_ref r = dvm_new_object(vm, dvm__class_by_desc(vm, "Ljava/lang/Class;"));
   struct dvm_object *o = dvm__obj(vm, r);
   if (o) { o->kind = DVM_OBJ_CLASS; o->klass = cls; ++o->pins; }
   cls->class_object = r;
   return r;
}

static const char *primitive_java_name(const char *desc)
{
   static const struct { const char *desc, *name; } names[] = {
      { "Z", "boolean" }, { "B", "byte" }, { "C", "char" },
      { "S", "short" }, { "I", "int" }, { "J", "long" },
      { "F", "float" }, { "D", "double" }, { "V", "void" },
   };
   for (size_t i = 0; desc && i < sizeof names / sizeof names[0]; ++i)
      if (!strcmp(desc, names[i].desc)) return names[i].name;
   return NULL;
}

static bool cl_getName(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   const char *n = (o && o->klass) ? o->klass->name : "java.lang.Object";
   const char *primitive = o && o->klass
      ? primitive_java_name(o->klass->desc) : NULL;
   if (primitive) n = primitive;
   char buf[512];
   snprintf(buf, sizeof buf, "%s", n);
   for (char *p = buf; *p; ++p) if (*p == '/') *p = '.';
   RETL(dvm_new_string(vm, buf));
}

static bool cl_getSimpleName(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                             int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   const char *n = (o && o->klass) ? o->klass->name : "Object";
   const char *primitive = o && o->klass
      ? primitive_java_name(o->klass->desc) : NULL;
   if (primitive) n = primitive;
   const char *slash = strrchr(n, '/');
   RETL(dvm_new_string(vm, slash ? slash + 1 : n));
}

static bool cl_forName(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   (void)self;
   const char *n = dvm_string_utf8(vm, ARG(0).l);
   if (!n) { dvm__throw(vm, "java/lang/ClassNotFoundException", "null"); return false; }
   /* forName() is how app code asks whether an optional dependency shipped
    * with this build or this device.  Handing back a Class for every name
    * turned that question into an unconditional yes — see dvm_class_exists(). */
   if (!dvm_class_exists(vm, n)) {
      dvm__throw(vm, "java/lang/ClassNotFoundException", "%s", n);
      return false;
   }
   char desc[512];
   snprintf(desc, sizeof desc, "L%s;", n);
   for (char *p = desc; *p; ++p) if (*p == '.') *p = '/';
   struct dvm_class *c = dvm__class_by_desc(vm, desc);
   /* forName(name) initializes the class, and forName(name, init, loader) does
    * when asked — that is the difference between a Kotlin `object` whose
    * INSTANCE is filled in and one whose INSTANCE is still null.  Netmarble's
    * Contents.Companion reaches its content objects exactly this way
    * (Class.forName(n).getField("INSTANCE").get(null)) and rejects a null as
    * "this class must inherit Contents.Global". */
   if (c && (nargs < 2 || args[1].i))
      (void)dvm_init_class(vm, c);
   RETL(class_object_for(vm, c));
}

static bool cl_getClassLoader(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   static dvm_ref loader;
   (void)self; (void)args; (void)nargs;
   if (!loader) {
      struct dvm_class *c = dvm__class_by_desc(vm, "Ljava/lang/ClassLoader;");
      loader = c ? dvm_new_object(vm, c) : 0;
      if (loader) dvm_pin(vm, loader);
   }
   RETL(loader);
}

/* ClassLoader.getResourceAsStream: APK/classpath entry as a stream, or null.
 * ServiceLoader reads META-INF/services/<iface> this way; answering unresolved
 * aborted kotlinx.coroutines' static init before the dispatcher existed. */
static bool cl_getResourceAsStream(struct dvm *vm, dvm_ref self,
                                   const union dvm_value *args, int nargs,
                                   union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *name = ARG(0).l ? dvm_string_utf8(vm, ARG(0).l) : NULL;
   if (!name || !*name) RETL(0);
   /* Strip a leading slash — ClassLoader names are relative to the classpath. */
   if (name[0] == '/') ++name;
   size_t len = 0;
   unsigned char *data = arm_exec_asset_read(name, &len);
   if (!data) RETL(0);
   dvm_ref bytes = dvm_new_array(vm, 'B', "B", (uint32_t)len);
   struct dvm_object *ao = bytes ? dvm__obj(vm, bytes) : NULL;
   if (ao && ao->data && len) memcpy(ao->data, data, len);
   free(data);
   if (!bytes) RETL(0);
   struct dvm_class *c =
      dvm__class_by_desc(vm, "Ljava/io/ByteArrayInputStream;");
   dvm_ref s = c ? dvm_new_object(vm, c) : 0;
   if (!s) RETL(0);
   union dvm_value ia[1] = { { .l = bytes } }, ignored = { 0 };
   /* st_init_bytes is defined later; set the JDK fields directly. */
   (void)dvm_set_field(vm, s, "buf", "[B", ia[0]);
   union dvm_value pos = { .i = 0 }, count = { .i = (int32_t)len };
   (void)dvm_set_field(vm, s, "pos", "I", pos);
   (void)dvm_set_field(vm, s, "count", "I", count);
   (void)ignored;
   RETL(s);
}

/* Resolve Class-relative resource names before handing them to the common
 * class-path reader.  ClassLoader names are rooted; Class names without a
 * leading slash are relative to the declaring class' package. */
static bool cl_resource_name(struct dvm *vm, dvm_ref self, dvm_ref name_ref,
                             bool class_relative, char *path, size_t cap)
{
   const char *name = name_ref ? dvm_string_utf8(vm, name_ref) : NULL;
   if (!name || !*name || !path || cap == 0) return false;
   if (*name == '/') {
      ++name;
      return snprintf(path, cap, "%s", name) < (int)cap;
   }
   if (class_relative) {
      struct dvm_object *o = dvm__obj(vm, self);
      const char *class_name = o && o->klass ? o->klass->name : NULL;
      const char *slash = class_name ? strrchr(class_name, '/') : NULL;
      if (slash) {
         const size_t package_len = (size_t)(slash - class_name + 1);
         if (package_len >= cap) return false;
         memcpy(path, class_name, package_len);
         return snprintf(path + package_len, cap - package_len, "%s", name) <
                (int)(cap - package_len);
      }
   }
   return snprintf(path, cap, "%s", name) < (int)cap;
}

static dvm_ref classpath_resource_stream(struct dvm *vm, const char *path)
{
   union dvm_value arg = { .l = dvm_new_string(vm, path) }, result = { 0 };
   if (!arg.l || !cl_getResourceAsStream(vm, 0, &arg, 1, &result)) return 0;
   return result.l;
}

static bool cl_class_getResourceAsStream(struct dvm *vm, dvm_ref self,
                                         const union dvm_value *args,
                                         int nargs, union dvm_value *out)
{
   (void)nargs;
   char path[PATH_MAX];
   if (!cl_resource_name(vm, self, ARG(0).l, true, path, sizeof path)) RETL(0);
   RETL(classpath_resource_stream(vm, path));
}

/* Build a URL only for an entry the package class path really contains.
 * Constructing the object directly also permits Android's jar:file: form;
 * URL(String) below deliberately accepts network protocols only. */
static dvm_ref classpath_resource_url(struct dvm *vm, const char *path)
{
   size_t len = 0;
   unsigned char *data = arm_exec_asset_read(path, &len);
   if (!data) return 0;
   free(data);

   const char *apk = lunaria_apk_mount_path();
   if (!apk) apk = "";
   const size_t need = strlen(apk) + strlen(path) + sizeof "jar:file:!/";
   char *spec = malloc(need);
   if (!spec) return 0;
   /* Android's JarURLConnection form is jar:file:/absolute.apk!/entry.  The
    * nested file URL has one slash from the absolute path, not a `file://`
    * authority; code which strips the literal "file:" relies on that. */
   snprintf(spec, need, "jar:file:%s!/%s", apk, path);
   struct dvm_class *uc = dvm__class_by_desc(vm, "Ljava/net/URL;");
   dvm_ref url = uc ? dvm_new_object(vm, uc) : 0;
   if (url) {
      union dvm_value value = { .l = dvm_new_string(vm, spec) };
      (void)dvm_set_field(vm, url, "url", "Ljava/lang/String;", value);
   }
   free(spec);
   return url;
}

