/* `ci` marks a map whose String keys compare without regard to case.
 *
 * One map on Android is built that way and it matters: HttpURLConnection's
 * getHeaderFields() returns a TreeMap over String.CASE_INSENSITIVE_ORDER,
 * because HTTP header names are case-insensitive and a server may send any
 * spelling.  A caller that looks up "x-amz-meta-af-auth-v1" in a plain map
 * gets nothing the moment the server capitalises it — and an SDK that
 * authenticates a response by that header reads "absent" as "forged". */
struct rt_map { uint32_t cap, size, ci; struct { dvm_ref k, v; } e[]; };

/* Key comparison for a map, which is key_eq() plus that one exception. */
static bool key_eq(struct dvm *vm, dvm_ref a, dvm_ref b);
static bool map_key_eq(struct dvm *vm, const struct rt_map *mp, dvm_ref a,
                       dvm_ref b)
{
   if (mp && mp->ci && a && b) {
      const char *x = dvm_string_utf8(vm, a), *y = dvm_string_utf8(vm, b);
      if (x && y) return !strcasecmp(x, y);
   }
   return key_eq(vm, a, b);
}

static bool map_init(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                     int nargs, union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   struct dvm_object *o = dvm__obj(vm, self);
   if (!o) RETV();
   free(o->data);
   o->data = calloc(1, sizeof(struct rt_map) + 8 * sizeof(*((struct rt_map *)0)->e));
   if (o->data) ((struct rt_map *)o->data)->cap = 8;
   RETV();
}

static bool map_put(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                    int nargs, union dvm_value *out)
{
   (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   if (!o) RETL(0);
   struct rt_map *mp = o->data;
   if (!mp) { map_init(vm, self, NULL, 0, out); mp = o->data; }
   if (!mp) RETL(0);
   for (uint32_t i = 0; i < mp->size; ++i) {
      if (!map_key_eq(vm, mp, mp->e[i].k, ARG(0).l)) continue;
      dvm_ref old = mp->e[i].v;
      mp->e[i].v = ARG(1).l;
      dvm_pin(vm, ARG(1).l);
      RETL(old);
   }
   if (mp->size == mp->cap) {
      uint32_t cap = mp->cap ? mp->cap * 2 : 8;
      struct rt_map *n = realloc(mp, sizeof *n + (size_t)cap * sizeof n->e[0]);
      if (!n) RETL(0);
      n->cap = cap;
      o->data = mp = n;
   }
   mp->e[mp->size].k = ARG(0).l;
   mp->e[mp->size].v = ARG(1).l;
   ++mp->size;
   dvm_pin(vm, ARG(0).l);
   dvm_pin(vm, ARG(1).l);
   RETL(0);
}

static bool map_get(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                    int nargs, union dvm_value *out)
{
   (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_map *mp = o ? o->data : NULL;
   for (uint32_t i = 0; mp && i < mp->size; ++i)
      if (map_key_eq(vm, mp, mp->e[i].k, ARG(0).l)) RETL(mp->e[i].v);
   RETL(0);
}

static bool map_containsKey(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                            int nargs, union dvm_value *out)
{
   (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_map *mp = o ? o->data : NULL;
   for (uint32_t i = 0; mp && i < mp->size; ++i)
      if (map_key_eq(vm, mp, mp->e[i].k, ARG(0).l)) RETI(1);
   RETI(0);
}

static bool map_remove(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_map *mp = o ? o->data : NULL;
   for (uint32_t i = 0; mp && i < mp->size; ++i) {
      if (!map_key_eq(vm, mp, mp->e[i].k, ARG(0).l)) continue;
      dvm_ref old = mp->e[i].v;
      memmove(&mp->e[i], &mp->e[i + 1], (mp->size - i - 1) * sizeof mp->e[0]);
      --mp->size;
      RETL(old);
   }
   RETL(0);
}

static bool map_size(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                     int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_map *mp = o ? o->data : NULL;
   RETI(mp ? (int32_t)mp->size : 0);
}

static bool map_clear(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                      int nargs, union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_map *mp = o ? o->data : NULL;
   if (mp) mp->size = 0;
   RETV();
}

/* The spec is assembled from the caller's format at run time; that is exactly
 * what String.format does, so the literal-format check cannot apply here. */
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wformat-nonliteral"

/* String.format — the conversions logging and URL building actually use.  An
 * unrecognised one is copied through verbatim, so a format this does not model
 * degrades to a readable message instead of losing it. */
static bool s_format(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                     int nargs, union dvm_value *out)
{
   (void)self;
   /* format(String, Object[]) and format(Locale, String, Object[]) */
   int fi = 0;
   if (nargs >= 3) fi = 1;
   const char *f = (fi < nargs && args[fi].l) ? dvm_string_utf8(vm, args[fi].l)
                                              : NULL;
   if (!f) RETL(dvm_new_string(vm, ""));
   struct dvm_object *va =
      (fi + 1 < nargs && args[fi + 1].l) ? dvm__obj(vm, args[fi + 1].l) : NULL;
   const uint32_t *items =
      (va && va->kind == DVM_OBJ_ARRAY) ? va->data : NULL;
   uint32_t nitems = items ? va->length : 0;

   struct rt_bytes b = { 0 };
   uint32_t next = 0;
   for (const char *p = f; *p; ++p) {
      if (*p != '%') {
         bytes_append(&b, p, 1);
         continue;
      }
      const char *start = p++;
      while (*p && strchr("-+ #0,(", *p)) ++p;
      while (*p >= '0' && *p <= '9') ++p;
      if (*p == '.') { ++p; while (*p >= '0' && *p <= '9') ++p; }
      char conv = *p;
      if (!conv) { bytes_append(&b, start, strlen(start)); break; }

      if (conv == '%') { bytes_append(&b, "%", 1); continue; }
      if (conv == 'n') { bytes_append(&b, "\n", 1); continue; }

      /* Rebuild the spec without the Java-only ',' and '(' flags, which
       * printf would reject. */
      char spec[40];
      size_t sl = 0;
      spec[sl++] = '%';
      for (const char *q = start + 1; q < p && sl < sizeof spec - 4; ++q)
         if (*q != ',' && *q != '(') spec[sl++] = *q;

      dvm_ref arg = next < nitems ? items[next++] : 0;
      char buf[512];
      switch (conv) {
      case 'd': case 'o': case 'x': case 'X': {
         /* %x, %X and %o print the two's complement in the *argument's* own
          * width: java formats a Byte of -13 as "f3", not as the 64-bit
          * sign extension "fffffffffffffff3".  Every "bytes to hex" helper
          * is String.format("%02x", b) over a byte[], so getting this wrong
          * turns a correct MD5 into a string that can never match — which is
          * how correctly downloaded pak files came to be rejected as
          * ErrorMD5Mismatch.  %d stays signed, as java has it. */
         long long v = (long long)box_get(vm, arg).j;
         if (conv != 'd') {
            struct dvm_class *bc = arg ? dvm_object_class(vm, arg) : NULL;
            const char *bn = bc ? bc->name : NULL;
            if (bn && !strcmp(bn, "java/lang/Byte"))
               v = (long long)(unsigned char)v;
            else if (bn && !strcmp(bn, "java/lang/Short"))
               v = (long long)(unsigned short)v;
            else if (!bn || strcmp(bn, "java/lang/Long"))
               v = (long long)(uint32_t)v;   /* Integer, and the default */
         }
         spec[sl++] = 'l'; spec[sl++] = 'l'; spec[sl++] = conv; spec[sl] = '\0';
         snprintf(buf, sizeof buf, spec, v);
         break;
      }
      case 'f': case 'e': case 'E': case 'g': case 'G': {
         spec[sl++] = conv; spec[sl] = '\0';
         snprintf(buf, sizeof buf, spec, box_get(vm, arg).d);
         break;
      }
      case 'c': {
         spec[sl++] = 'c'; spec[sl] = '\0';
         snprintf(buf, sizeof buf, spec, (int)box_get(vm, arg).i);
         break;
      }
      case 'b': {
         spec[sl++] = 's'; spec[sl] = '\0';
         snprintf(buf, sizeof buf, spec, arg ? "true" : "false");
         break;
      }
      case 's': case 'S': default: {
         union dvm_value one = { .l = arg }, str = { 0 };
         (void)s_valueOf_obj(vm, 0, &one, 1, &str);
         const char *s = str.l ? dvm_string_utf8(vm, str.l) : NULL;
         spec[sl++] = 's'; spec[sl] = '\0';
         snprintf(buf, sizeof buf, spec, s ? s : "null");
         if (conv == 'S')
            for (char *q = buf; *q; ++q) *q = (char)toupper((unsigned char)*q);
         break;
      }
      }
      bytes_append(&b, buf, strlen(buf));
   }

   dvm_ref r = dvm_new_string_n(vm, b.p ? (const char *)b.p : "", b.len);
   free(b.p);
   RETL(r);
}

#pragma GCC diagnostic pop

/* ------------------------------------------------------------------------ *
 * The table
 * ------------------------------------------------------------------------ */

struct rt_method {
   const char *name, *sig;
   dvm_builtin_fn fn;
   uint32_t access;
};

struct rt_field {
   const char *name, *type;
};

struct rt_class {
   const char *desc;
   const char *super;
   const struct rt_method *methods;
   const struct rt_field *fields;
   /* Interfaces the class implements, NULL-terminated.  Only `super` used to
    * be modelled, so `check-cast Ljava/util/Map;` on a builtin HashMap threw
    * ClassCastException — real code casts collections to their interfaces
    * constantly.  class_assignable() already walks dvm_class::ifaces; this is
    * how a builtin gets any. */
   const char *const *ifaces;
   /* Static fields.  A builtin that answers a static field only through a
    * special case in Field.get() is a class whose state cannot be *found*:
    * getDeclaredFields() lists nothing, so the discovery loop a library uses
    * to reach it walks away empty — which is how protobuf's
    * `for (Field f : Unsafe.class.getDeclaredFields())` ended up with no
    * Unsafe at all.  Optional: omitted positional initialisers stay NULL. */
   const struct rt_field *sfields;
   bool is_interface;
   const char *generic_signature;
};

#define M(n, s, f)   { n, s, f, 0 }
#define SM(n, s, f)  { n, s, f, DEX_ACC_STATIC }
#define M_END        { NULL, NULL, NULL, 0 }
#define F_END        { NULL, NULL }

/* Pattern.matches(regex, input) is the one-shot form of
 * compile(regex).matcher(input).matches() — the whole input has to match. */
static bool regex_static_matches(struct dvm *vm, dvm_ref self,
                                 const union dvm_value *args, int nargs,
                                 union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *expr = dvm_string_utf8(vm, ARG(0).l);
   const char *input = ARG(1).l ? dvm_string_utf8(vm, ARG(1).l) : NULL;
   char *ere = regex_java_to_ere(expr, NULL);
   regex_t re;
   if (!ere || regcomp(&re, ere, REG_EXTENDED) != 0) {
      free(ere);
      dvm__throw(vm, "java/util/regex/PatternSyntaxException", "%s",
                 expr ? expr : "null");
      return false;
   }
   free(ere);
   regmatch_t m = { 0 };
   int rc = input ? regexec(&re, input, 1, &m, 0) : REG_NOMATCH;
   bool whole = rc == 0 && m.rm_so == 0 && (size_t)m.rm_eo == strlen(input);
   regfree(&re);
   RETI(whole);
}

static bool s_matches(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                      int nargs, union dvm_value *out)
{
   /* String.matches(regex) ≡ Pattern.matches(regex, this). */
   union dvm_value a[2] = { nargs > 0 ? ARG(0) : (union dvm_value){ 0 },
                            { .l = self } };
   return regex_static_matches(vm, 0, a, 2, out);
}

