   if (!hay) RETI(-1);
   int ch = nargs > 1 ? (int)(ARG(1).u & 0xffff) : 0;
   int32_t from = nargs > 2 ? ARG(2).i : (int32_t)hn - 1;
   if (from >= (int32_t)hn) from = (int32_t)hn - 1;
