   if (kind == 'L' && sv) RETL(dvm_new_string(vm, sv));
   union dvm_value v = { .i = iv };
   if (kind == 'Z') RETL(box_make(vm, "Ljava/lang/Boolean;", v));
   if (kind == 'I') RETL(box_make(vm, "Ljava/lang/Integer;", v));
