/* java.util.concurrent BlockingQueue.  Volley hands requests between its
 * dispatchers through these.  Backed by the same list storage: only one
 * bytecode thread runs at a time, so nothing can be added while a take() is in
 * flight and a take() on an empty queue cannot succeed later in this slice.
 * That is what blocking means here, so the thread parks: the exception ends
 * the run rather than being offered to the app's catch clause.  Reporting it
 * as an ordinary InterruptedException instead let Volley's dispatcher loop
 * catch it and go straight back round — a spin that burned the whole slice
 * and logged "Ignoring spurious interrupt" a hundred thousand times. */
static bool q_take(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                   int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   struct rt_list *l = list_of(vm, self);
   /* A thread with a stack of its own waits here for real.  Parking unwinds to
    * the top of the thread and re-enters run() from the beginning, which is
    * the right shape for a queued Runnable and quite wrong for a take() that
    * a producer on another thread is about to satisfy. */
   if ((!l || !l->size) && dvm_on_bytecode_thread()) {
      uint64_t deadline = dvm__now_ms() + DVM_BLOCK_MAX_MS;
      while (dvm__now_ms() < deadline) {
         uint64_t now = dvm__now_ms();
         dvm_gil_wait_for(vm, self,
                          (unsigned)(deadline > now ? deadline - now : 1));
         l = list_of(vm, self);          /* re-read: another thread ran */
         if (l && l->size) break;
      }
   }
   if (!l || !l->size) {
      if (dvm__sched_trace())
         fprintf(stderr, "[sched] take @%x: empty → park\n", self);
      dvm__throw(vm, "java/lang/InterruptedException", "queue is empty");
      vm->parked = true;
      return false;
   }
   if (dvm__sched_trace())
      fprintf(stderr, "[sched] take @%x: %u queued\n", self, l->size);
   dvm_ref head = l->items[0];
   memmove(&l->items[0], &l->items[1], (l->size - 1) * sizeof(dvm_ref));
   --l->size;
   RETL(head);
}

static bool q_poll(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                   int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   struct rt_list *l = list_of(vm, self);
   if (!l || !l->size) RETL(0);
   dvm_ref head = l->items[0];
   memmove(&l->items[0], &l->items[1], (l->size - 1) * sizeof(dvm_ref));
   --l->size;
   RETL(head);
}

static bool q_peek(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                   int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   struct rt_list *l = list_of(vm, self);
   RETL(l && l->size ? l->items[0] : 0);
}

/* put()/offer() are add() with the queue's return convention. */
static bool q_offer(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                    int nargs, union dvm_value *out)
{
   union dvm_value ignored = { 0 };
   (void)list_add(vm, self, args, nargs, &ignored);
   dvm_gil_notify_for(self);
   RETI(1);
}

static bool q_put(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                  int nargs, union dvm_value *out)
{
   union dvm_value ignored = { 0 };
   (void)list_add(vm, self, args, nargs, &ignored);
   dvm_gil_notify_for(self);
   RETV();
}

static bool q_drainTo(struct dvm *vm, dvm_ref self,
                      const union dvm_value *args, int nargs,
                      union dvm_value *out)
{
   dvm_ref destination = nargs ? ARG(0).l : 0;
   if (!destination || destination == self) {
      dvm__throw(vm, "java/lang/IllegalArgumentException",
                 "drainTo destination must be a different collection");
      return false;
   }
   struct rt_list *source = list_of(vm, self);
   uint32_t limit = source ? source->size : 0;
   if (nargs > 1 && ARG(1).i >= 0 && (uint32_t)ARG(1).i < limit)
      limit = (uint32_t)ARG(1).i;
   struct dvm_class *dc = dvm_object_class(vm, destination);
   struct dvm_method *add = dc
      ? dvm_find_method(vm, dc, "add", "(Ljava/lang/Object;)Z") : NULL;
   uint32_t moved = 0;
   while (source && source->size && moved < limit) {
      union dvm_value item = { .l = source->items[0] }, accepted = { 0 };
      if (!add || !dvm_call(vm, add, destination, &item, 1, &accepted))
         break;
      memmove(&source->items[0], &source->items[1],
              (source->size - 1) * sizeof source->items[0]);
      --source->size;
      ++moved;
   }
   RETI((int32_t)moved);
}

