static bool instant_atOffset(struct dvm *vm, dvm_ref self,
                             const union dvm_value *args, int nargs,
                             union dvm_value *out)
{
   (void)nargs;
   RETL(jt_new(vm, "Ljava/time/OffsetDateTime;", jt_millis(vm, self),
               zone_offset_seconds(vm, ARG(0).l)));
}

