#define JT_FIELD(fn, expr)                                                    \
   static bool fn(struct dvm *vm, dvm_ref self, const union dvm_value *args,  \
                  int nargs, union dvm_value *out)                            \
   {                                                                          \
      (void)args; (void)nargs;                                                \
      struct tm tm; int32_t sub = 0, off = 0;                                 \
      jt_break(vm, self, &tm, &sub, &off);                                    \
      RETI(expr);                                                             \
   }

