   static bool fn(struct dvm *vm, dvm_ref self, const union dvm_value *args,  \
                  int nargs, union dvm_value *out)                            \
   { (void)vm; (void)self; (void)args; (void)nargs; body; RETV(); }
#define RT_GLI(fn, expr)                                                      \
