static bool li_from(struct dvm *vm, dvm_ref self,
                    const union dvm_value *args, int nargs,
                    union dvm_value *out)
{
   (void)self;
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/view/LayoutInflater;");
   dvm_ref inflater = c ? dvm_new_object(vm, c) : 0;
   if (inflater) {
      union dvm_value context = { .l = nargs > 0 ? ARG(0).l : 0 };
      (void)dvm_set_field(vm, inflater, "context", "Landroid/content/Context;",
                          context);
   }
   RETL(inflater);
}

static bool li_get_factory(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)args; (void)nargs;
   union dvm_value factory = { 0 };
   (void)dvm_get_field(vm, self, "factory", "Ljava/lang/Object;", &factory);
   RETL(factory.l);
}

static bool li_set_factory(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   union dvm_value factory = { .l = nargs > 0 ? ARG(0).l : 0 };
   (void)dvm_set_field(vm, self, "factory", "Ljava/lang/Object;", factory);
   RETV();
}

static bool li_clone(struct dvm *vm, dvm_ref self,
                     const union dvm_value *args, int nargs,
                     union dvm_value *out)
{
   union dvm_value made = { 0 };
   if (!li_from(vm, 0, args, nargs, &made)) return false;
   union dvm_value factory = { 0 };
   (void)dvm_get_field(vm, self, "factory", "Ljava/lang/Object;", &factory);
   if (made.l)
      (void)dvm_set_field(vm, made.l, "factory", "Ljava/lang/Object;", factory);
   RETL(made.l);
}

static uint16_t ax_u16(const unsigned char *p)
{
   uint16_t v; memcpy(&v, p, sizeof v); return v;
}

static uint32_t ax_u32(const unsigned char *p)
{
   uint32_t v; memcpy(&v, p, sizeof v); return v;
}

static size_t ax_len8(const unsigned char *p, size_t left, uint32_t *value)
{
   if (!left) return 0;
   if (!(p[0] & 0x80)) { *value = p[0]; return 1; }
   if (left < 2) return 0;
   *value = ((uint32_t)(p[0] & 0x7f) << 8) | p[1]; return 2;
}

static char **ax_string_pool(const unsigned char *b, size_t n,
                             uint32_t *count_out)
{
   size_t pos = n >= 8 ? ax_u16(b + 2) : n;
   while (pos + 28 <= n) {
      uint16_t type = ax_u16(b + pos), hs = ax_u16(b + pos + 2);
      uint32_t size = ax_u32(b + pos + 4);
      if (size < hs || pos + size > n) break;
      if (type != 0x0001) { pos += size; continue; }
      uint32_t count = ax_u32(b + pos + 8);
      uint32_t flags = ax_u32(b + pos + 16);
      uint32_t strings_off = ax_u32(b + pos + 20);
      if (hs + (uint64_t)count * 4 > size || strings_off > size) return NULL;
      char **strings = calloc(count ? count : 1, sizeof *strings);
      if (!strings) return NULL;
      for (uint32_t i = 0; i < count; ++i) {
         uint32_t off = ax_u32(b + pos + hs + i * 4u);
         size_t q = pos + strings_off + off;
         if (q >= pos + size) continue;
         if (flags & 0x100) {
            uint32_t chars = 0, bytes = 0;
            size_t used = ax_len8(b + q, pos + size - q, &chars);
            if (!used) continue;
            q += used;
            used = ax_len8(b + q, pos + size - q, &bytes);
            if (!used || q + used + bytes > pos + size) continue;
            q += used;
            strings[i] = strndup((const char *)b + q, bytes);
         } else {
            if (q + 2 > pos + size) continue;
            uint32_t chars = ax_u16(b + q); q += 2;
            if (chars & 0x8000) {
               if (q + 2 > pos + size) continue;
               chars = ((chars & 0x7fff) << 16) | ax_u16(b + q); q += 2;
            }
            if (q + (uint64_t)chars * 2 > pos + size) continue;
            strings[i] = malloc((size_t)chars + 1);
            if (!strings[i]) continue;
            /* Resource tag and attribute names are ASCII.  Preserve other
             * BMP text losslessly enough for class/resource identifiers. */
            for (uint32_t k = 0; k < chars; ++k) {
               uint16_t c = ax_u16(b + q + k * 2u);
               strings[i][k] = c < 0x80 ? (char)c : '?';
            }
            strings[i][chars] = '\0';
         }
      }
      *count_out = count;
      return strings;
   }
   return NULL;
}

static dvm_ref li_make_view(struct dvm *vm, const char *tag, dvm_ref context)
{
   char desc[512];
   if (!tag || !*tag) return 0;
   const char *name = tag;
   const char *class_name = NULL;
   if (!strcmp(name, "view")) class_name = "android/view/View";
   if (class_name) snprintf(desc, sizeof desc, "L%s;", class_name);
   else if (strchr(name, '.')) {
      size_t j = 1; desc[0] = 'L';
      for (size_t i = 0; name[i] && j + 2 < sizeof desc; ++i)
         desc[j++] = name[i] == '.' ? '/' : name[i];
      desc[j++] = ';'; desc[j] = '\0';
   } else {
      snprintf(desc, sizeof desc, "Landroid/widget/%s;", name);
   }
   struct dvm_class *c = dvm__class_by_desc(vm, desc);
   if (!c && !strchr(name, '.')) {
      snprintf(desc, sizeof desc, "Landroid/view/%s;", name);
      c = dvm__class_by_desc(vm, desc);
   }
   if (!c) c = dvm__class_by_desc(vm, "Landroid/view/ViewGroup;");
   dvm_ref view = c ? dvm_new_object(vm, c) : 0;
   if (!view) return 0;
   union dvm_value cv = { .l = context };
   (void)dvm_set_field(vm, view, "context", "Landroid/content/Context;", cv);

   /* Constructors establish widget-owned fields and are part of inflation.
    * AttributeSet is supplied as null until its general binary-XML facade is
    * exposed; framework widgets are required to accept that just like a
    * programmatically constructed view. */
   struct dvm_method *ctor = dvm_find_method(
      vm, c, "<init>", "(Landroid/content/Context;Landroid/util/AttributeSet;)V");
   union dvm_value ignored = { 0 };
   if (ctor) {
      union dvm_value a[2] = { { .l = context }, { .l = 0 } };
      if (!dvm_call(vm, ctor, view, a, 2, &ignored)) dvm_clear_exception(vm);
   } else {
      ctor = dvm_find_method(vm, c, "<init>", "(Landroid/content/Context;)V");
      if (ctor && !dvm_call(vm, ctor, view, &cv, 1, &ignored))
         dvm_clear_exception(vm);
   }
   return view;
}

/* --- inflated layout attributes ----------------------------------------- *
 *
 * The inflater used to read exactly two attributes out of a compiled layout —
 * `id` and `layout` (for <include>) — and drop the rest on the floor.  A tree
 * built that way has the right shape and no geometry at all: no width, no
 * height, no orientation, no weight, no text, no colour.  That is enough for
 * findViewById() to answer, which is all the emulator ever asked of it, but it
 * is not enough to put the layout on screen, and it is not what the platform
 * does.  Everything below turns a compiled Res_value into the field the widget
 * would have been constructed with.
 *
 * Value types are the Res_value ones from androidfw/ResourceTypes.h.
 */
enum {
   AX_REFERENCE  = 0x01,
   AX_ATTRIBUTE  = 0x02,
   AX_STRING     = 0x03,
   AX_FLOAT      = 0x04,
   AX_DIMENSION  = 0x05,
   AX_FRACTION   = 0x06,
   AX_INT_DEC    = 0x10,
   AX_INT_HEX    = 0x11,
   AX_INT_BOOL   = 0x12,
   AX_COLOR_ARGB8 = 0x1c,
   AX_COLOR_RGB8  = 0x1d,
   AX_COLOR_ARGB4 = 0x1e,
   AX_COLOR_RGB4  = 0x1f,
};

/* A length in device pixels.  MATCH_PARENT (-1) and WRAP_CONTENT (-2) arrive
 * as plain ints and have to survive as themselves. */
static int32_t ax_dimension_px(uint8_t type, uint32_t data)
{
   if (type == AX_DIMENSION)
      return (int32_t)lrintf(android_complex_dimension((int32_t)data));
   if (type == AX_FLOAT) {
      float f; uint32_t u = data; memcpy(&f, &u, sizeof f);
      return (int32_t)lrintf(f);
   }
   /* A layout is free to write @dimen/foo anywhere a length is expected.  The
    * reference has to be followed, because the id itself is a large positive
    * number and would otherwise be used as a length in pixels. */
   if (type == AX_REFERENCE && data) {
      int32_t value = 0; const char *sv = NULL;
      if (arm_exec_apk_resource_value(data, &value, &sv) && !sv)
         return (int32_t)lrintf(android_complex_dimension(value));
      return 0;
   }
   return (int32_t)data;
}

/* Colours can be written inline (#RRGGBB) or named through a colour resource
 * or a ColorStateList; the reference is resolved the same way the platform
 * resolves it, through the resource table. */
static bool ax_color(struct dvm *vm, uint8_t type, uint32_t data,
                     int32_t *out_argb)
{
   (void)vm;
   if (type >= AX_COLOR_ARGB8 && type <= AX_COLOR_RGB4) {
      *out_argb = (int32_t)data;
      return true;
   }
   if (type == AX_REFERENCE && data) {
      int32_t value = 0; const char *sv = NULL;
      int kind = arm_exec_apk_resource_value(data, &value, &sv);
      /* A colour resource resolves to an int; a ColorStateList resolves to a
       * file path, and its default colour is not knowable from here. */
      if (kind && kind != 'L') { *out_argb = value; return true; }
   }
   return false;
}

/* Text is either literal or an @string reference. */
static dvm_ref ax_string(struct dvm *vm, uint8_t type, uint32_t data,
                         char *const *strings, uint32_t nstrings)
{
   if (type == AX_STRING && data < nstrings && strings[data])
      return dvm_new_string(vm, strings[data]);
   if (type == AX_REFERENCE && data) {
      int32_t value = 0; const char *sv = NULL;
      if (arm_exec_apk_resource_value(data, &value, &sv) == 'L' && sv)
         return dvm_new_string(vm, sv);
   }
   return 0;
}

/* Same two widths as ui_int(): `visibility` is an int and `disabled` is a
 * boolean, and the inflater has no reason to know which is which. */
static void ax_set_int(struct dvm *vm, dvm_ref view, const char *field,
                       int32_t value)
{
   union dvm_value v = { .i = value };
   if (!dvm_set_field(vm, view, field, "I", v))
      (void)dvm_set_field(vm, view, field, "Z", v);
}

/* android:gravity and android:layout_gravity are bit masks, not enums; the
 * constants are the platform's. */
static void ax_apply_attribute(struct dvm *vm, dvm_ref view, const char *name,
                               uint8_t type, uint32_t data,
                               char *const *strings, uint32_t nstrings)
{
   if (!view || !name) return;

   /* Geometry the parent uses to place this child. */
   if (!strcmp(name, "layout_width"))
      { ax_set_int(vm, view, "layoutWidth", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "layout_height"))
      { ax_set_int(vm, view, "layoutHeight", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "layout_weight")) {
      float f = 0.0f;
      if (type == AX_FLOAT) { uint32_t u = data; memcpy(&f, &u, sizeof f); }
      else f = (float)(int32_t)data;
      union dvm_value v = { .f = f };
      (void)dvm_set_field(vm, view, "layoutWeight", "F", v);
      return;
   }
   if (!strcmp(name, "layout_margin")) {
      int32_t m = ax_dimension_px(type, data);
      ax_set_int(vm, view, "marginLeft", m);
      ax_set_int(vm, view, "marginTop", m);
      ax_set_int(vm, view, "marginRight", m);
      ax_set_int(vm, view, "marginBottom", m);
      return;
   }
   if (!strcmp(name, "layout_marginLeft") || !strcmp(name, "layout_marginStart"))
      { ax_set_int(vm, view, "marginLeft", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "layout_marginTop"))
      { ax_set_int(vm, view, "marginTop", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "layout_marginRight") || !strcmp(name, "layout_marginEnd"))
      { ax_set_int(vm, view, "marginRight", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "layout_marginBottom"))
      { ax_set_int(vm, view, "marginBottom", ax_dimension_px(type, data)); return; }

   if (!strcmp(name, "padding")) {
      int32_t m = ax_dimension_px(type, data);
      ax_set_int(vm, view, "paddingLeft", m);
      ax_set_int(vm, view, "paddingTop", m);
      ax_set_int(vm, view, "paddingRight", m);
      ax_set_int(vm, view, "paddingBottom", m);
      return;
   }
   if (!strcmp(name, "paddingLeft") || !strcmp(name, "paddingStart"))
      { ax_set_int(vm, view, "paddingLeft", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "paddingTop"))
      { ax_set_int(vm, view, "paddingTop", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "paddingRight") || !strcmp(name, "paddingEnd"))
      { ax_set_int(vm, view, "paddingRight", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "paddingBottom"))
      { ax_set_int(vm, view, "paddingBottom", ax_dimension_px(type, data)); return; }

   if (!strcmp(name, "orientation"))
      { ax_set_int(vm, view, "orientation", (int32_t)data); return; }
   if (!strcmp(name, "gravity"))
      { ax_set_int(vm, view, "gravity", (int32_t)data); return; }
   if (!strcmp(name, "layout_gravity"))
      { ax_set_int(vm, view, "layoutGravity", (int32_t)data); return; }
   if (!strcmp(name, "visibility"))
      { ax_set_int(vm, view, "visibility", (int32_t)data); return; }
   if (!strcmp(name, "enabled"))
      { ax_set_int(vm, view, "disabled", data ? 0 : 1); return; }
   if (!strcmp(name, "layout_centerInParent") ||
       !strcmp(name, "layout_centerHorizontal"))
      { ax_set_int(vm, view, "centerInParent", data ? 1 : 0); return; }
   if (!strcmp(name, "layout_alignParentBottom"))
      { ax_set_int(vm, view, "alignParentBottom", data ? 1 : 0); return; }

   /* Backgrounds arrive as a colour, a drawable reference, or a state list.
    * Only a resolved colour can be painted; the reference is kept either way
    * so a widget that reads it back sees what the layout said. */
   if (!strcmp(name, "background")) {
      int32_t argb = 0;
      if (ax_color(vm, type, data, &argb))
         ax_set_int(vm, view, "backgroundColor", argb);
      if (type == AX_REFERENCE)
         ax_set_int(vm, view, "backgroundResource", (int32_t)data);
      return;
   }
   if (!strcmp(name, "src") || !strcmp(name, "srcCompat"))
      { ax_set_int(vm, view, "imageResource", (int32_t)data); return; }

   if (!strcmp(name, "text")) {
      union dvm_value v = { .l = ax_string(vm, type, data, strings, nstrings) };
      if (v.l) (void)dvm_set_field(vm, view, "text",
                                   "Ljava/lang/CharSequence;", v);
      return;
   }
   if (!strcmp(name, "hint")) {
      union dvm_value v = { .l = ax_string(vm, type, data, strings, nstrings) };
      if (v.l) (void)dvm_set_field(vm, view, "hint",
                                   "Ljava/lang/CharSequence;", v);
      return;
   }
   if (!strcmp(name, "textSize")) {
      union dvm_value v = { .f = (float)ax_dimension_px(type, data) };
      (void)dvm_set_field(vm, view, "textSize", "F", v);
      return;
   }
   if (!strcmp(name, "textColor")) {
      int32_t argb = 0;
      if (ax_color(vm, type, data, &argb))
         ax_set_int(vm, view, "textColor", argb);
      return;
   }
   if (!strcmp(name, "textStyle"))
      { ax_set_int(vm, view, "textStyle", (int32_t)data); return; }
   if (!strcmp(name, "maxLines") || !strcmp(name, "lines"))
      { ax_set_int(vm, view, "maxLines", (int32_t)data); return; }

   /* app: namespace attributes the SDK's own layouts use. */
   if (!strcmp(name, "cardCornerRadius") || !strcmp(name, "radius"))
      { ax_set_int(vm, view, "cornerRadius", ax_dimension_px(type, data)); return; }
   if (!strcmp(name, "cardBackgroundColor")) {
      int32_t argb = 0;
      if (ax_color(vm, type, data, &argb))
         ax_set_int(vm, view, "backgroundColor", argb);
      return;
   }
}

static dvm_ref li_inflate_resource(struct dvm *vm, dvm_ref context,
                                   uint32_t resource, unsigned depth)
{
   if (depth > 16 || !resource) return 0;
   int32_t iv = 0; const char *path = NULL;
   if (arm_exec_apk_resource_value(resource, &iv, &path) != 'L' || !path)
      return 0;
   if (getenv("LUNARIA_DVM_TRACE_LAYOUT"))
      fprintf(stderr, "[dvm] layout 0x%08x -> %s\n", resource, path);
   size_t n = 0;
   unsigned char *b = arm_exec_asset_read(path, &n);
   if (!b || n < 8 || ax_u16(b) != 0x0003) { free(b); return 0; }
   uint32_t nstrings = 0;
   char **strings = ax_string_pool(b, n, &nstrings);
   if (!strings) { free(b); return 0; }
   dvm_ref stack[64] = { 0 }, root = 0;
   unsigned sp = 0;
   size_t pos = ax_u16(b + 2);
   while (pos + 8 <= n) {
      uint16_t type = ax_u16(b + pos), hs = ax_u16(b + pos + 2);
      uint32_t size = ax_u32(b + pos + 4);
      if (size < hs || pos + size > n) break;
      if (type == 0x0102 && pos + 36 <= n) {
         uint32_t name_i = ax_u32(b + pos + 20);
         const char *tag = name_i < nstrings ? strings[name_i] : NULL;
         uint16_t attr_start = ax_u16(b + pos + 24);
         uint16_t attr_size = ax_u16(b + pos + 26);
         uint16_t attr_count = ax_u16(b + pos + 28);
         uint32_t id = 0, include = 0;
         size_t attrs = pos + 16u + attr_start;
         for (uint16_t i = 0; attr_size >= 20 && i < attr_count; ++i) {
            size_t q = attrs + (size_t)i * attr_size;
            if (q + 20 > pos + size) break;
            uint32_t ai = ax_u32(b + q + 4);
            const char *an = ai < nstrings ? strings[ai] : NULL;
            uint8_t value_type = b[q + 15];
            uint32_t data = ax_u32(b + q + 16);
            if (an && !strcmp(an, "id") && value_type == 0x01) id = data;
            if (an && !strcmp(an, "layout") && value_type == 0x01)
               include = data;
         }
         if (getenv("LUNARIA_DVM_TRACE_LAYOUT"))
            fprintf(stderr, "[dvm] layout tag depth=%u %s id=0x%08x include=0x%08x\n",
                    sp, tag ? tag : "?", id, include);
         dvm_ref parent = sp ? stack[sp - 1] : 0;
         if (tag && !strcmp(tag, "include")) {
            dvm_ref child = li_inflate_resource(vm, context, include, depth + 1);
            if (child && id) {
               union dvm_value v = { .i = (int32_t)id };
               (void)dvm_set_field(vm, child, "id", "I", v);
            }
            if (parent && child) {
               union dvm_value a = { .l = child }, ignored = { 0 };
               (void)vg_add_view(vm, parent, &a, 1, &ignored);
            }
            if (sp < 64) stack[sp++] = 0;
         } else if (tag && !strcmp(tag, "merge")) {
            if (sp < 64) stack[sp++] = parent;
         } else {
            dvm_ref view = li_make_view(vm, tag, context);
            if (view && id) {
               union dvm_value v = { .i = (int32_t)id };
               (void)dvm_set_field(vm, view, "id", "I", v);
            }
            /* Attributes are applied after construction, the same order the
             * platform uses: the constructor establishes the widget's
             * defaults, then the layout overrides them. */
            for (uint16_t i = 0; view && attr_size >= 20 && i < attr_count; ++i) {
               size_t q = attrs + (size_t)i * attr_size;
               if (q + 20 > pos + size) break;
               uint32_t ai = ax_u32(b + q + 4);
               const char *an = ai < nstrings ? strings[ai] : NULL;
               ax_apply_attribute(vm, view, an, b[q + 15], ax_u32(b + q + 16),
                                  strings, nstrings);
            }
            if (parent && view) {
               union dvm_value a = { .l = view }, ignored = { 0 };
               (void)vg_add_view(vm, parent, &a, 1, &ignored);
            }
            if (!root) root = view;
            if (sp < 64) stack[sp++] = view;
         }
      } else if (type == 0x0103 && sp) {
         --sp;
      }
      pos += size;
   }
   for (uint32_t i = 0; i < nstrings; ++i) free(strings[i]);
   free(strings); free(b);
   return root;
}

static bool li_inflate(struct dvm *vm, dvm_ref self,
                       const union dvm_value *args, int nargs,
                       union dvm_value *out)
{
   if (getenv("LUNARIA_DVM_TRACE_LAYOUT") && nargs > 0) {
      int32_t value = 0; const char *path = NULL;
      int kind = arm_exec_apk_resource_value((uint32_t)ARG(0).i,
                                              &value, &path);
      fprintf(stderr, "[dvm] inflate resource 0x%08x kind=%d path=%s\n",
              (unsigned)ARG(0).i, kind, path ? path : "(none)");
   }
   union dvm_value context = { 0 };
   (void)dvm_get_field(vm, self, "context", "Landroid/content/Context;",
                       &context);
   dvm_ref view = nargs ? li_inflate_resource(
      vm, context.l, (uint32_t)ARG(0).i, 0) : 0;
   dvm_ref parent = nargs > 1 ? ARG(1).l : 0;
   /* inflate(resource, root) is specified as
    * inflate(resource, root, root != null). */
   bool attach = parent && (nargs < 3 || ARG(2).i);
   if (parent && view && attach) {
      union dvm_value a = { .l = view }, ignored = { 0 };
      (void)vg_add_view(vm, parent, &a, 1, &ignored);
      RETL(parent);
   }
   RETL(view);
}

static const struct rt_field rt_layout_inflater_fields[] = {
   { "context", "Landroid/content/Context;" },
   { "factory", "Ljava/lang/Object;" },
   F_END,
};

static const struct rt_method rt_layout_inflater[] = {
   SM("from", "(Landroid/content/Context;)Landroid/view/LayoutInflater;", li_from),
   M("getFactory", "()Landroid/view/LayoutInflater$Factory;", li_get_factory),
   M("getFactory2", "()Landroid/view/LayoutInflater$Factory2;", li_get_factory),
   M("setFactory", "(Landroid/view/LayoutInflater$Factory;)V", li_set_factory),
   M("setFactory2", "(Landroid/view/LayoutInflater$Factory2;)V", li_set_factory),
   M("cloneInContext", "(Landroid/content/Context;)Landroid/view/LayoutInflater;",
     li_clone),
   M("inflate", "(ILandroid/view/ViewGroup;)Landroid/view/View;", li_inflate),
   M("inflate", "(ILandroid/view/ViewGroup;Z)Landroid/view/View;", li_inflate),
   M_END,
};

static bool typeface_create(struct dvm *vm, dvm_ref self,
                            const union dvm_value *args, int nargs,
                            union dvm_value *out)
{
   (void)self; (void)args; (void)nargs;
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/graphics/Typeface;");
   RETL(c ? dvm_new_object(vm, c) : 0);
}

static const struct rt_method rt_typeface[] = {
   SM("createFromAsset",
      "(Landroid/content/res/AssetManager;Ljava/lang/String;)Landroid/graphics/Typeface;",
      typeface_create),
   SM("create", "(Ljava/lang/String;I)Landroid/graphics/Typeface;",
      typeface_create),
   M_END,
};

/* android.app.NativeActivity.
 *
 * On a device these three do the work of starting a native app: onCreate
 * loads the library named by android.app.lib_name and calls
 * ANativeActivity_onCreate through it, and onStart/onResume forward to the
 * activity's callbacks.  Lunaria does all of that itself, from the loader —
 * it is what the emulator *is* — before any of this bytecode runs: the
 * library is loaded, ANativeActivity_onCreate has been called with a real
 * ANativeActivity, and the pump is driving the callbacks.
 *
 * So when a subclass such as UE4's GameActivity calls super.onCreate(), there
 * is genuinely nothing left for it to do.  Doing it twice would be the bug:
 * a second ANativeActivity_onCreate on the same library re-enters the NDK
 * glue's thread startup with a half-built state. */
static const struct rt_method rt_native_activity[] = {
   M("onCreate", "(Landroid/os/Bundle;)V", empty_void),
   M("onStart", "()V", empty_void),
   M("onResume", "()V", empty_void),
   M_END,
};

/* AlertDialog.Builder is stateful on Android: its mutators return the same
 * builder and create() materializes a distinct Dialog carrying that state.
 * Keeping that contract matters even for a headless backend because guest
 * code commonly builds dialogs through a fluent call chain. */
/* --- the emulator's widget presentation layer --------------------------- *
 *
 * Everything above keeps a faithful *book* of the Android view tree: parents,
 * children, ids, text, colours, the geometry the layout asked for.  None of it
 * ever reached a pixel, because Lunaria had no measure/layout/draw pass and no
 * window compositor.  For a game that draws its own frames with GL that was
 * invisible — right up to the point where the SDK puts a modal dialog in front
 * of the player and waits.  Netmarble's terms-of-service gate is exactly that:
 * a native layout (nm_tos_single.xml — title, a card with the terms, an Agree
 * and a Disagree row) whose Agree button the boot flow will not pass without.
 *
 * This is the missing half.  The view tree is translated into an HTML/CSS
 * document and handed to luna-ui through luna_overlay, which composites it
 * over the guest's finished frame — the position a real compositor puts a
 * dialog window in.  A click on an element is routed back to the OnClickListener
 * of the View it stands for.
 *
 * The mapping is deliberately narrow and literal: LinearLayout is a flex box in
 * its declared orientation, layout_weight is flex-grow, MATCH_PARENT/
 * WRAP_CONTENT are 100%/auto, and everything else stacks in document order.
 * That is not a general Android layout engine, and it does not pretend to be
 * one; it is enough to place, read and press the dialogs an SDK puts up.
 */

#include "luna_overlay.h"

/* Gravity bits, from android.view.Gravity. */
#define UI_GRAVITY_CENTER_H 0x01
#define UI_GRAVITY_CENTER_V 0x10
#define UI_GRAVITY_RIGHT    0x05
#define UI_GRAVITY_BOTTOM   0x50

/* A growing text buffer.  The document is built once per change, not per
 * frame, so a plain realloc buffer is the whole story. */
struct ui_buf { char *p; size_t len, cap; };

static void ui_put(struct ui_buf *b, const char *s, size_t n)
{
   if (!b->p && b->cap) return;                   /* a previous grow failed */
   if (b->len + n + 1 > b->cap) {
      size_t cap = b->cap ? b->cap * 2 : 4096;
      while (cap < b->len + n + 1) cap *= 2;
      char *q = realloc(b->p, cap);
      if (!q) { free(b->p); b->p = NULL; b->cap = 1; return; }
      b->p = q; b->cap = cap;
   }
   memcpy(b->p + b->len, s, n);
   b->len += n;
   b->p[b->len] = '\0';
}

static void ui_puts(struct ui_buf *b, const char *s) { ui_put(b, s, strlen(s)); }

static void ui_printf(struct ui_buf *b, const char *fmt, ...)
{
   char tmp[512];
   va_list ap;
   va_start(ap, fmt);
   int n = vsnprintf(tmp, sizeof tmp, fmt, ap);
   va_end(ap);
   if (n > 0) ui_put(b, tmp, (size_t)n < sizeof tmp ? (size_t)n : sizeof tmp - 1);
}

/* Text out of the guest goes into markup, so the five characters that would
 * otherwise be parsed as markup have to stop being those characters. */
static void ui_put_escaped(struct ui_buf *b, const char *s)
{
   for (; s && *s; ++s) {
      switch (*s) {
      case '&': ui_puts(b, "&amp;"); break;
      case '<': ui_puts(b, "&lt;"); break;
      case '>': ui_puts(b, "&gt;"); break;
      case '"': ui_puts(b, "&quot;"); break;
      default: ui_put(b, s, 1); break;
      }
   }
}

/* Field lookup matches on the descriptor, so an int read of a field declared
 * `Z` finds nothing and answers 0 — which is a valid value, so the miss is
 * invisible.  Both widths live in the same slot here, and which of the two a
 * given flag was declared with is not something the caller should have to
 * track, so both are tried. */
static int32_t ui_int(struct dvm *vm, dvm_ref o, const char *name)
{
   union dvm_value v = { 0 };
   if (dvm_get_field(vm, o, name, "I", &v)) return v.i;
   if (dvm_get_field(vm, o, name, "Z", &v)) return v.i;
   return 0;
}

static float ui_float(struct dvm *vm, dvm_ref o, const char *name)
{
   union dvm_value v = { 0 };
   (void)dvm_get_field(vm, o, name, "F", &v);
   return v.f;
}

static dvm_ref ui_obj(struct dvm *vm, dvm_ref o, const char *name,
                      const char *type)
{
   union dvm_value v = { 0 };
   (void)dvm_get_field(vm, o, name, type, &v);
   return v.l;
}

/* The simple name of a view's class, for the element's CSS class. */
static const char *ui_class_simple_name(struct dvm *vm, dvm_ref view)
{
   struct dvm_class *c = dvm_object_class(vm, view);
   const char *n = c ? dvm_class_name(c) : NULL;
   if (!n) return "view";
   const char *slash = strrchr(n, '/');
   return slash ? slash + 1 : n;
}

/* Whether `view` is a `want` (or derives from one), by walking the declared
 * superclass chain the same way the VM's own cast check does. */
static bool ui_is_a(struct dvm *vm, dvm_ref view, const char *want)
{
   struct dvm_class *c = dvm_object_class(vm, view);
   for (int guard = 0; c && guard < 32; ++guard) {
      const char *n = dvm_class_name(c);
      if (n && !strcmp(n, want)) return true;
      const char *super = dvm_class_super_name(c);
      if (!super) return false;
      c = dvm_find_class(vm, super);
   }
   return false;
}

/* A CharSequence is not always a String — SpannableString and StringBuilder
 * are the two an app reaches for constantly — and reading only Strings would
 * silently drop the label. */
static const char *ui_text_of(struct dvm *vm, dvm_ref view)
{
   dvm_ref t = ui_obj(vm, view, "text", "Ljava/lang/CharSequence;");
   if (!t) return NULL;
   const char *s = dvm_string_utf8(vm, t);
   if (s) return s;
   struct dvm_class *c = dvm_object_class(vm, t);
   struct dvm_method *m =
      c ? dvm_find_method(vm, c, "toString", "()Ljava/lang/String;") : NULL;
   union dvm_value out = { 0 };
   if (m && dvm_call(vm, m, t, NULL, 0, &out) && out.l)
      return dvm_string_utf8(vm, out.l);
   dvm_clear_exception(vm);
   return NULL;
}

/* Android colours are 0xAARRGGBB ints; CSS wants the alpha separately and as a
 * fraction.  A fully transparent colour is "no background", which is also what
 * a view that was never given one has. */
static void ui_color_css(char *out, size_t n, int32_t argb)
{
   unsigned a = ((uint32_t)argb >> 24) & 0xff;
   snprintf(out, n, "rgba(%u,%u,%u,%.3f)",
            ((uint32_t)argb >> 16) & 0xff, ((uint32_t)argb >> 8) & 0xff,
            (uint32_t)argb & 0xff, a / 255.0);
}

/* A background can be a colour attribute the inflater resolved, or a Drawable
 * the code set later; both end up as one colour here. */
static bool ui_background_color(struct dvm *vm, dvm_ref view, int32_t *out)
{
   int32_t c = ui_int(vm, view, "backgroundColor");
   if (c) { *out = c; return true; }
   dvm_ref bg = ui_obj(vm, view, "background",
                       "Landroid/graphics/drawable/Drawable;");
   if (bg) {
      c = ui_int(vm, bg, "color");
      if (c) { *out = c; return true; }
   }
   return false;
}

/* MATCH_PARENT / WRAP_CONTENT / an explicit length, as the CSS the parent's
 * layout mode makes of it. */
static void ui_emit_length(struct ui_buf *b, const char *prop, int32_t v)
{
   if (v == -1) ui_printf(b, "%s:100%%;", prop);
   else if (v > 0) ui_printf(b, "%s:%dpx;", prop, v);
   /* WRAP_CONTENT (-2) and an unset 0 are both "as big as the content", which
    * is CSS's default; saying so explicitly would override a flex basis. */
}

static void ui_emit_view(struct dvm *vm, struct ui_buf *b, struct ui_buf *css,
                         dvm_ref view, int parent_orientation, unsigned depth);

/* --- RecyclerView --------------------------------------------------------
 *
 * A RecyclerView holds no children of its own: its LayoutManager asks the
 * Adapter for as many item views as fit and places them.  There is no measure
 * pass here to run a LayoutManager in, so this does the LayoutManager's job
 * directly, through the Adapter's own public entry points — the same two calls
 * (createViewHolder, bindViewHolder) a LinearLayoutManager makes, minus the
 * recycling, which only exists to avoid re-creating views while scrolling.
 *
 * Without this the list is empty, and an empty list is not a neutral answer:
 * the terms dialog's required checkboxes live in one, so the player has
 * nothing to agree to.
 */
static bool ui_is_recycler(struct dvm *vm, dvm_ref view)
{
   return ui_is_a(vm, view, "androidx/recyclerview/widget/RecyclerView");
}

/* An exception thrown inside the widget layer would otherwise vanish: the
 * caller is the emulator, not the app, so nothing else will ever report it. */
static void ui_report_exception(struct dvm *vm, const char *what)
{
   dvm_ref e = dvm_exception(vm);
   char buf[256] = "";
   if (e) dvm_describe_exception(vm, e, buf, sizeof buf);
   fprintf(stderr, "[ui] %s threw %s\n", what, buf[0] ? buf : "(no exception)");
   dvm_clear_exception(vm);
}

static bool ui_call(struct dvm *vm, dvm_ref self, const char *method,
                    const char *sig, const union dvm_value *args, int nargs,
                    union dvm_value *out)
{
   struct dvm_class *c = dvm_object_class(vm, self);
   struct dvm_method *m = c ? dvm_find_method(vm, c, method, sig) : NULL;
   if (!m) {
      fprintf(stderr, "[ui] %s%s not found on %s\n", method, sig,
              c ? dvm_class_name(c) : "?");
      return false;
   }
   if (!dvm_call(vm, m, self, args, nargs, out)) {
      ui_report_exception(vm, method);
      return false;
   }
   return true;
}

/* Holders belong to the RecyclerView, not to a single layout pass: a real one
 * creates each once and rebinds it afterwards.  Recreating them here would
 * throw away the item views on every rebuild, and with them everything the
 * player had done to the widgets inside — the terms dialog's checkboxes went
 * back to unchecked the moment the tick was reported. */
#define UI_MAX_RECYCLERS 8
#define UI_MAX_ITEMS 128
static struct ui_recycler {
   dvm_ref view;
   dvm_ref holders[UI_MAX_ITEMS];
   int32_t count;
} g_ui_recyclers[UI_MAX_RECYCLERS];

/* The cache entry for a view, or NULL when it is not a list we drive. */
static struct ui_recycler *ui_recycler_of(dvm_ref view)
{
   for (int i = 0; i < UI_MAX_RECYCLERS; ++i)
      if (g_ui_recyclers[i].view == view) return &g_ui_recyclers[i];
   return NULL;
}

static struct ui_recycler *ui_recycler_for(struct dvm *vm, dvm_ref view)
{
   struct ui_recycler *free_slot = NULL;
   for (int i = 0; i < UI_MAX_RECYCLERS; ++i) {
      if (g_ui_recyclers[i].view == view) return &g_ui_recyclers[i];
      if (!g_ui_recyclers[i].view && !free_slot) free_slot = &g_ui_recyclers[i];
   }
   if (free_slot) {
      free_slot->view = view;
      free_slot->count = 0;
      dvm_pin(vm, view);
   }
   return free_slot;
}

static void ui_recycler_drop(struct dvm *vm, struct ui_recycler *r)
{
   for (int32_t i = 0; i < r->count; ++i) dvm_unpin(vm, r->holders[i]);
   r->count = 0;
}

static void ui_fill_recycler(struct dvm *vm, dvm_ref view)
{
   union dvm_value adapter = { 0 };
   if (!ui_call(vm, view, "getAdapter",
                "()Landroidx/recyclerview/widget/RecyclerView$Adapter;",
                NULL, 0, &adapter) || !adapter.l)
      return;
   union dvm_value count = { 0 };
   if (!ui_call(vm, adapter.l, "getItemCount", "()I", NULL, 0, &count))
      return;
   if (count.i < 0 || count.i > UI_MAX_ITEMS) return;

   struct ui_recycler *r = ui_recycler_for(vm, view);
   if (!r) return;

   /* A different item count means the data set changed shape; the holders it
    * produced no longer stand for anything. */
   if (r->count != count.i) {
      ui_recycler_drop(vm, r);
      for (int32_t i = 0; i < count.i; ++i) {
         union dvm_value type = { 0 }, at = { .i = i };
         (void)ui_call(vm, adapter.l, "getItemViewType", "(I)I", &at, 1, &type);
         union dvm_value make[2] = { { .l = view }, { .i = type.i } };
         union dvm_value holder = { 0 };
         if (!ui_call(vm, adapter.l, "createViewHolder",
                      "(Landroid/view/ViewGroup;I)"
                      "Landroidx/recyclerview/widget/RecyclerView$ViewHolder;",
                      make, 2, &holder) || !holder.l)
            break;
         dvm_pin(vm, holder.l);
         r->holders[r->count++] = holder.l;
         /* The Recycler is what normally stamps the owning RecyclerView onto a
          * holder, and ViewHolder.getAdapterPosition() returns NO_POSITION
          * without it.  Adapters guard their listeners with exactly that check
          * — Netmarble's item listener returns immediately on NO_POSITION —
          * so leaving it unset makes every checkbox change a no-op that
          * reports nothing.  The emulator is standing in for the Recycler
          * here, so it owes the same stamp. */
         {
            union dvm_value owner = { .l = view };
            (void)dvm_set_field(vm, holder.l, "mOwnerRecyclerView",
                                "Landroidx/recyclerview/widget/RecyclerView;",
                                owner);
         }
         /* The item view is *not* added to the RecyclerView's child list.
          * RecyclerView keeps its own parallel bookkeeping (ChildHelper, the
          * LayoutParams that carry the ViewHolder back-pointer) that only its
          * own Recycler fills in, and a child it did not put there makes its
          * internals disagree with themselves — notifyDataSetChanged() walked
          * the children and cast their LayoutParams to
          * RecyclerView.LayoutParams, which these are not.  The emulator is
          * standing in for the LayoutManager, so the item views are its own;
          * only the parent link is published, because that is what hit
          * testing and getParent() need. */
         dvm_ref item = ui_obj(vm, holder.l, "itemView", "Landroid/view/View;");
         if (item) {
            union dvm_value p = { .l = view };
            (void)dvm_set_field(vm, item, "parent",
                                "Landroid/view/ViewParent;", p);
         }
      }
   }

   /* Rebind every time: that is how an adapter publishes a change, and it is
    * the only signal there is here that its data moved. */
   for (int32_t i = 0; i < r->count; ++i) {
      union dvm_value bind[2] = { { .l = r->holders[i] }, { .i = i } };
      union dvm_value ignored = { 0 };
      (void)ui_call(vm, adapter.l, "bindViewHolder",
                    "(Landroidx/recyclerview/widget/RecyclerView$ViewHolder;I)V",
                    bind, 2, &ignored);
   }
}

/* Children, in the order the parent added them — except a RecyclerView, whose
 * children are the item views the emulator's own list layout produced. */
static void ui_emit_children(struct dvm *vm, struct ui_buf *b,
                             struct ui_buf *css, dvm_ref view,
                             int orientation, unsigned depth)
{
   struct ui_recycler *r = ui_recycler_of(view);
   if (r) {
      for (int32_t i = 0; i < r->count; ++i) {
         dvm_ref item = ui_obj(vm, r->holders[i], "itemView",
                               "Landroid/view/View;");
         ui_emit_view(vm, b, css, item, orientation, depth + 1);
      }
      return;
   }
   dvm_ref kids = ui_obj(vm, view, "children", "Ljava/util/List;");
   struct rt_list *l = kids ? list_of(vm, kids) : NULL;
   for (uint32_t i = 0; l && i < l->size; ++i)
      ui_emit_view(vm, b, css, l->items[i], orientation, depth + 1);
}

/* parent_orientation: 1 vertical, 0 horizontal, -1 not a flex parent.
 *
 * The structure goes into `b` and the per-view declarations into `css`, as a
 * rule keyed on the element's id.  They are not written inline: luna-ui's
 * inline-style path applies only part of what it parses (padding, flex,
 * align-self, opacity and visibility are all dropped there) and caps the
 * attribute at 256 bytes, while the stylesheet path supports the whole set. */
static void ui_emit_view(struct dvm *vm, struct ui_buf *b, struct ui_buf *css,
                         dvm_ref view, int parent_orientation, unsigned depth)
{
   if (!view || depth > 32) return;

   int32_t visibility = ui_int(vm, view, "visibility");
   if (visibility == 8) return;             /* GONE: not laid out at all */

   const char *simple = ui_class_simple_name(vm, view);
   bool is_linear = ui_is_a(vm, view, "android/widget/LinearLayout");
   int32_t orientation = is_linear ? ui_int(vm, view, "orientation") : -1;
   bool is_compound = ui_is_a(vm, view, "android/widget/CompoundButton");

   if (ui_is_recycler(vm, view)) ui_fill_recycler(vm, view);
   dvm_ref kids = ui_obj(vm, view, "children", "Ljava/util/List;");
   struct rt_list *l = kids ? list_of(vm, kids) : NULL;
   struct ui_recycler *cache = ui_recycler_of(view);
   bool has_children = cache ? cache->count > 0 : (l && l->size);

   struct ui_buf *b2 = css;
   ui_printf(b2, "#v%u{", (unsigned)view);

   /* How this element lays its own children out. */
   if (is_linear)
      ui_printf(b2, "display:flex;flex-direction:%s;",
                orientation == 1 ? "column" : "row");
   else if (is_compound)
      /* A CompoundButton is a box and a label side by side. */
      ui_puts(b2, "display:flex;flex-direction:row;align-items:center;");
   else if (has_children)
      /* FrameLayout, RelativeLayout, CardView, RecyclerView and the app's own
       * containers.  Stacking in document order is what a single-child
       * container does exactly, and a multi-child one approximately. */
      ui_puts(b2, "display:flex;flex-direction:column;");

   /* How the parent sizes this element. */
   int32_t lw = ui_int(vm, view, "layoutWidth");
   int32_t lh = ui_int(vm, view, "layoutHeight");
   float weight = ui_float(vm, view, "layoutWeight");
   if (weight > 0.0f) {
      /* layout_weight distributes the space left over along the parent's
       * axis; the 0dp the layout pairs it with means "take it all from the
       * weight", which is flex-basis:0. */
      ui_printf(b2, "flex:%g 1 0;", (double)weight);
      if (parent_orientation == 1) ui_emit_length(b2, "width", lw);
      else ui_emit_length(b2, "height", lh);
   } else {
      ui_emit_length(b2, "width", lw);
      ui_emit_length(b2, "height", lh);
   }

   int32_t ml = ui_int(vm, view, "marginLeft"), mt = ui_int(vm, view, "marginTop");
   int32_t mr = ui_int(vm, view, "marginRight");
   int32_t mb = ui_int(vm, view, "marginBottom");
   if (ml || mt || mr || mb)
      ui_printf(b2, "margin:%dpx %dpx %dpx %dpx;", mt, mr, mb, ml);
   int32_t pl = ui_int(vm, view, "paddingLeft"), pt = ui_int(vm, view, "paddingTop");
   int32_t pr = ui_int(vm, view, "paddingRight");
   int32_t pb = ui_int(vm, view, "paddingBottom");
   if (pl || pt || pr || pb)
      ui_printf(b2, "padding:%dpx %dpx %dpx %dpx;", pt, pr, pb, pl);

   int32_t bg = 0;
   if (ui_background_color(vm, view, &bg)) {
      char c[64];
      ui_color_css(c, sizeof c, bg);
      ui_printf(b2, "background:%s;", c);
   }
   int32_t radius = ui_int(vm, view, "cornerRadius");
   if (radius > 0) ui_printf(b2, "border-radius:%dpx;", radius);

   /* Text presentation.  A view with no text of its own ignores all of it. */
   const char *text = ui_text_of(vm, view);
   if (text && *text) {
      float size = ui_float(vm, view, "textSize");
      if (size > 0.0f) ui_printf(b2, "font-size:%gpx;", (double)size);
      int32_t color = ui_int(vm, view, "textColor");
      if (color) {
         char c[64];
         ui_color_css(c, sizeof c, color);
         ui_printf(b2, "color:%s;", c);
      }
      if (ui_int(vm, view, "textStyle") & 1) ui_puts(b2, "font-weight:bold;");
   }

   int32_t gravity = ui_int(vm, view, "gravity");
   if (gravity & UI_GRAVITY_CENTER_H) ui_puts(b2, "text-align:center;");
   if (is_linear || has_children) {
      /* On a flex container gravity is the alignment of the children. */
      bool vertical = orientation == 1 || !is_linear;
      if (gravity & UI_GRAVITY_CENTER_H)
         ui_puts(b2, vertical ? "align-items:center;" : "justify-content:center;");
      if (gravity & UI_GRAVITY_CENTER_V)
         ui_puts(b2, vertical ? "justify-content:center;" : "align-items:center;");
   }

   /* layout_gravity is how the *parent* places this child: align-self across
    * the parent's axis, and an auto margin along it. */
   int32_t lg = ui_int(vm, view, "layoutGravity");
   if (lg) {
      bool column = parent_orientation != 0;
      if (lg & UI_GRAVITY_CENTER_H)
         ui_puts(b2, column ? "align-self:center;"
                            : "margin-left:auto;margin-right:auto;");
      if (lg & UI_GRAVITY_CENTER_V)
         ui_puts(b2, column ? "margin-top:auto;margin-bottom:auto;"
                            : "align-self:center;");
      if ((lg & UI_GRAVITY_RIGHT) == UI_GRAVITY_RIGHT)
         ui_puts(b2, column ? "align-self:flex-end;" : "margin-left:auto;");
      if ((lg & UI_GRAVITY_BOTTOM) == UI_GRAVITY_BOTTOM)
         ui_puts(b2, column ? "margin-top:auto;" : "align-self:flex-end;");
   }

   /* RelativeLayout's alignParentBottom, in a container that stacks: take all
    * the space above.  It is the rule the SDK's dialogs use to pin their
    * action button below the list. */
   if (ui_int(vm, view, "alignParentBottom")) ui_puts(b2, "margin-top:auto;");

   if (visibility == 4) ui_puts(b2, "visibility:hidden;");

   bool disabled = ui_int(vm, view, "disabled") != 0;
   if (disabled) ui_puts(b2, "opacity:0.45;");

   dvm_ref listener = ui_obj(vm, view, "clickListener",
                             "Landroid/view/View$OnClickListener;");
   if ((listener || is_compound) && !disabled) ui_puts(b2, "cursor:pointer;");
   ui_puts(b2, "}");

   ui_printf(b, "<div id=\"v%u\" class=\"w %s\">", (unsigned)view, simple);

   /* A CompoundButton's box comes from a state-list drawable on the device.
    * Drawables are not rasterised here, so the emulator draws the box itself
    * — without it a checkbox is an unlabelled blank and the dialog it gates
    * cannot be answered. */
   /* The box and the label carry the owning view's id with a suffix: luna-ui
    * reports the element that was hit, not an ancestor, so a press that lands
    * on the label has to identify the same View as one on the box. */
   if (is_compound) {
      bool checked = ui_int(vm, view, "checked") != 0;
      ui_printf(b, "<div id=\"v%ub\" class=\"cbox%s\"></div>", (unsigned)view,
                checked ? " on" : "");
   }
   if (text && *text) {
      ui_printf(b, "<span id=\"v%ut\" class=\"label\">", (unsigned)view);
      ui_put_escaped(b, text);
      ui_puts(b, "</span>");
   }
   ui_emit_children(vm, b, css, view, is_linear ? orientation : -1, depth);
   ui_puts(b, "</div>");
}

/* Windows currently up, innermost last.  A dialog is a window; so is the
 * Activity's own content view when something put one there. */
#define UI_MAX_WINDOWS 8
static dvm_ref g_ui_windows[UI_MAX_WINDOWS];
static int g_ui_nwindows;
static bool g_ui_dirty;
static bool g_ui_building;
static struct dvm *g_ui_vm;

/* Clicks come back from the presenting thread; they are dispatched on the
 * thread that drains the pending queue, which is where every other callback
 * the app posted to the main looper runs. */
static dvm_ref g_ui_clicks[16];
static int g_ui_nclicks;
static pthread_mutex_t g_ui_click_lock = PTHREAD_MUTEX_INITIALIZER;

static void ui_click_from_overlay(const char *id)
{
   if (!id || id[0] != 'v') return;
   unsigned long ref = strtoul(id + 1, NULL, 10);
   if (!ref) return;
   pthread_mutex_lock(&g_ui_click_lock);
   if (g_ui_nclicks < (int)(sizeof g_ui_clicks / sizeof g_ui_clicks[0]))
      g_ui_clicks[g_ui_nclicks++] = (dvm_ref)ref;
   pthread_mutex_unlock(&g_ui_click_lock);
}

/* The content view of a Dialog, or of a Window. */
static dvm_ref ui_window_content(struct dvm *vm, dvm_ref window)
{
   dvm_ref v = ui_obj(vm, window, "contentView", "Landroid/view/View;");
   if (v) return v;
   dvm_ref w = ui_obj(vm, window, "window", "Landroid/view/Window;");
   if (w) return ui_obj(vm, w, "contentView", "Landroid/view/View;");
   return 0;
}

/* The sheet is fixed: everything that varies about a view is written inline,
 * because it comes from the guest's own attributes rather than from a theme
 * this side gets to choose. */
static const char *ui_stylesheet(void)
{
   return
      "body{margin:0;background:transparent;font-size:14px;color:#ffffff;}"
      ".scrim{position:fixed;left:0;top:0;width:100%;height:100%;"
      "background:rgba(0,0,0,0.6);}"
      ".root{position:fixed;left:0;top:0;width:100%;height:100%;"
      "display:flex;flex-direction:column;box-sizing:border-box;}"
      ".w{box-sizing:border-box;}"
      ".label{flex:1 1 auto;}"
      /* The check box a CompoundButton would have drawn from its drawable. */
      ".cbox{width:18px;height:18px;flex:0 0 auto;margin-right:8px;"
      "border:2px solid #8a8f9a;border-radius:3px;background:#ffffff;}"
      ".cbox.on{background:#2b6fd8;border-color:#2b6fd8;}";
}

static void ui_rebuild(struct dvm *vm)
{
   g_ui_dirty = false;
   if (!g_ui_nwindows) {
      luna_overlay_set_document(NULL, NULL);
      return;
   }
   struct ui_buf b = { 0 }, css = { 0 };
   g_ui_building = true;
   ui_puts(&css, ui_stylesheet());
   ui_puts(&b, "<body><div class=\"scrim\"></div>");
   for (int i = 0; i < g_ui_nwindows; ++i) {
      dvm_ref content = ui_window_content(vm, g_ui_windows[i]);
      if (!content) continue;
      ui_puts(&b, "<div class=\"root\">");
      ui_emit_view(vm, &b, &css, content, -1, 0);
      ui_puts(&b, "</div>");
   }
   ui_puts(&b, "</body>");
   g_ui_building = false;
   if (b.p && css.p) {
      if (getenv("LUNARIA_UI_DUMP"))
         fprintf(stderr, "[ui] document (%zu bytes):\n%s\n[ui] style (%zu bytes):\n%s\n",
                 b.len, b.p, css.len, css.p);
      luna_overlay_set_document(b.p, css.p);
   }
   free(b.p);
   free(css.p);
}

/* Android finds the deepest view under the touch that is clickable, which for
 * a listener set in code means the nearest ancestor that has one. */
/* A view acts on a touch when it has a listener, when it was made clickable,
 * or when it is a CompoundButton — which is clickable by construction, because
 * pressing it is how it changes state. */
static bool ui_is_clickable(struct dvm *vm, dvm_ref view)
{
   return ui_obj(vm, view, "clickListener",
                 "Landroid/view/View$OnClickListener;") != 0 ||
          ui_int(vm, view, "clickable") != 0 ||
          ui_is_a(vm, view, "android/widget/CompoundButton");
}

static dvm_ref ui_click_target(struct dvm *vm, dvm_ref view)
{
   for (int guard = 0; view && guard < 32; ++guard) {
      /* A disabled view swallows the touch without acting on it, and so does
       * everything inside it; the press does not fall through to a parent. */
      if (ui_int(vm, view, "disabled")) return 0;
      if (ui_is_clickable(vm, view)) return view;
      view = ui_obj(vm, view, "parent", "Landroid/view/ViewParent;");
   }
   return 0;
}

/* View.performClick(), in the order the platform runs it: CompoundButton
 * toggles first and only then lets the OnClickListener see the click, so a
 * listener that reads isChecked() gets the state the press produced. */
static void ui_dispatch_click(struct dvm *vm, dvm_ref clicked)
{
   dvm_ref target = ui_click_target(vm, clicked);
   if (!target) {
      if (getenv("LUNARIA_UI_DUMP"))
         fprintf(stderr, "[ui] click on v%u: nothing clickable up the tree\n",
                 (unsigned)clicked);
      return;
   }
   if (ui_is_a(vm, target, "android/widget/CompoundButton")) {
      union dvm_value ignored = { 0 };
      if (!compound_toggle(vm, target, NULL, 0, &ignored))
         ui_report_exception(vm, "toggle");
   }
   dvm_ref listener = ui_obj(vm, target, "clickListener",
                             "Landroid/view/View$OnClickListener;");
   if (!listener) {
      fprintf(stderr, "[ui] click v%u (no OnClickListener)\n", (unsigned)target);
      return;
   }
   struct dvm_class *c = dvm_object_class(vm, listener);
   struct dvm_method *m =
      c ? dvm_find_method(vm, c, "onClick", "(Landroid/view/View;)V") : NULL;
   fprintf(stderr, "[ui] click v%u -> %s.onClick\n", (unsigned)target,
           c ? dvm_class_name(c) : "?");
   if (!m) return;
   union dvm_value a = { .l = target }, ignored = { 0 };
   if (!dvm_call(vm, m, listener, &a, 1, &ignored))
      ui_report_exception(vm, "onClick");
}

/* --- what the rest of the runtime calls -------------------------------- */

/* A view changed in a way that changes pixels. */
static void ui_invalidate(void)
{
   /* Building the document runs guest code (a RecyclerView's adapter creates
    * and binds its item views), and that code sets exactly the fields this
    * watches.  Without the guard the rebuild would mark itself stale for
    * ever. */
   if (g_ui_nwindows && !g_ui_building) g_ui_dirty = true;
}

static void ui_window_shown(struct dvm *vm, dvm_ref window)
{
   g_ui_vm = vm;
   for (int i = 0; i < g_ui_nwindows; ++i)
      if (g_ui_windows[i] == window) { g_ui_dirty = true; return; }
   if (g_ui_nwindows >= UI_MAX_WINDOWS) return;
   luna_overlay_set_click_handler(ui_click_from_overlay);
   dvm_pin(vm, window);
   g_ui_windows[g_ui_nwindows++] = window;
   fprintf(stderr, "[ui] window %u shown (%d up)\n", (unsigned)window,
           g_ui_nwindows);
   g_ui_dirty = true;
}

static void ui_window_hidden(struct dvm *vm, dvm_ref window)
{
   for (int i = 0; i < g_ui_nwindows; ++i) {
      if (g_ui_windows[i] != window) continue;
      memmove(&g_ui_windows[i], &g_ui_windows[i + 1],
              (size_t)(g_ui_nwindows - i - 1) * sizeof g_ui_windows[0]);
      --g_ui_nwindows;
      /* The item views die with the dialog; keeping them pinned would keep a
       * whole view tree alive for a window that is gone. */
      if (!g_ui_nwindows)
         for (int k = 0; k < UI_MAX_RECYCLERS; ++k)
            if (g_ui_recyclers[k].view) {
               ui_recycler_drop(vm, &g_ui_recyclers[k]);
               dvm_unpin(vm, g_ui_recyclers[k].view);
               g_ui_recyclers[k].view = 0;
            }
      dvm_unpin(vm, window);
      fprintf(stderr, "[ui] window %u hidden (%d up)\n", (unsigned)window,
              g_ui_nwindows);
      g_ui_dirty = true;
      return;
   }
}


/* ------------------------------------------------------------------------ *
 * The input method, on the guest's side
 *
 * On a device this is two things at once: a window that produces characters,
 * and a window that takes up room.  Both halves matter, and the second is the
 * one that is easy to leave out — an app does not ask "is a keyboard up", it
 * measures how much shorter its own window became.  UE4's GameActivity does
 * exactly that (GameActivity$10.onGlobalLayout: it compares the decor view's
 * drawing rect with the window's visible display frame and calls anything
 * under 200px "no keyboard"), and everything downstream of it — repositioning
 * the hidden EditText, nativeVirtualKeyboardShown(), and the TextWatcher that
 * only reports changes while that field is on screen — is gated on the answer.
 *
 * So the emulator's input method reports its own geometry, and a layout pass
 * runs when it appears and disappears.  luna_ime.c owns the panel and the
 * editing; this side owns the View it is connected to.
 * ------------------------------------------------------------------------ */

/* The height the panel gives the connected field, in surface pixels.  It has
 * to agree with .luna-ime-field in luna_ime.c: this is the number the app
 * reads back through getHeight() to decide where to put its own copy. */
#define RT_IME_FIELD_H 52

static dvm_ref g_ime_view;    /* the View showSoftInput() was called on */
static int     g_ime_band;    /* surface px the panel covers, 0 while down */

static int rt_surface_w(void) { int w = arm_exec_fb_width();  return w > 0 ? w : 0; }
static int rt_surface_h(void) { int h = arm_exec_fb_height(); return h > 0 ? h : 0; }

static void rect_fill(struct dvm *vm, dvm_ref rect, int l, int t, int r, int b)
{
   if (!rect) return;
   rt_set_int(vm, rect, "left", l);
   rt_set_int(vm, rect, "top", t);
   rt_set_int(vm, rect, "right", r);
   rt_set_int(vm, rect, "bottom", b);
}

/* A view's own size.
 *
 * There is no layout pass in this emulator, so a view that nothing assigned
 * bounds to has no size to report — and 0 is the honest answer for it.  One
 * case is not a guess, though: the root of a window fills that window, which
 * is what makes the decor view's drawing rect a real rectangle and lets the
 * comparison above mean something. */
static int32_t view_span(struct dvm *vm, dvm_ref v, bool vertical)
{
   int32_t lo = ui_int(vm, v, vertical ? "top" : "left");
   int32_t hi = ui_int(vm, v, vertical ? "bottom" : "right");
   if (hi > lo) return hi - lo;
   if (!ui_obj(vm, v, "parent", "Landroid/view/ViewParent;"))
      return vertical ? rt_surface_h() : rt_surface_w();
   return 0;
}

static bool view_get_width(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)args; (void)nargs;
   RETI(view_span(vm, self, false));
}

static bool view_get_height(struct dvm *vm, dvm_ref self,
                            const union dvm_value *args, int nargs,
                            union dvm_value *out)
{
   (void)args; (void)nargs;
   RETI(view_span(vm, self, true));
}

static bool view_get_drawing_rect(struct dvm *vm, dvm_ref self,
                                  const union dvm_value *args, int nargs,
                                  union dvm_value *out)
{
   (void)out;
   rect_fill(vm, nargs > 0 ? ARG(0).l : 0, 0, 0,
             view_span(vm, self, false), view_span(vm, self, true));
   RETV();
}

/* The part of the window the user can still see — the surface, less whatever
 * the system has put over it.  Here that is the input method's band, and
 * nothing else: there is no status bar and no navigation bar. */
static bool view_get_visible_display_frame(struct dvm *vm, dvm_ref self,
                                           const union dvm_value *args,
                                           int nargs, union dvm_value *out)
{
   (void)self; (void)out;
   int h = rt_surface_h();
   rect_fill(vm, nargs > 0 ? ARG(0).l : 0, 0, 0, rt_surface_w(),
             h - (g_ime_band < h ? g_ime_band : h));
   RETV();
}

static bool rect_width(struct dvm *vm, dvm_ref self,
                       const union dvm_value *args, int nargs,
                       union dvm_value *out)
{
   (void)args; (void)nargs;
   RETI(rt_get_int(vm, self, "right") - rt_get_int(vm, self, "left"));
}

static bool rect_height(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   (void)args; (void)nargs;
   RETI(rt_get_int(vm, self, "bottom") - rt_get_int(vm, self, "top"));
}

/* TextView.setWidth() sets the view's width outright, which is a layout
 * result, not a request: getWidth() has to answer it afterwards. */
static bool text_set_width(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)out;
   int32_t w = nargs > 0 ? ARG(0).i : 0;
   rt_set_int(vm, self, "right", rt_get_int(vm, self, "left") + w);
   RETV();
}

/* The caret, which here belongs to the input method's own field. */
static bool text_set_selection(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   (void)out;
   rt_set_int(vm, self, "selectionStart", nargs > 0 ? ARG(0).i : 0);
   rt_set_int(vm, self, "selectionEnd",
              nargs > 1 ? ARG(1).i : (nargs > 0 ? ARG(0).i : 0));
   RETV();
}

static bool view_clear_focus(struct dvm *vm, dvm_ref self,
                             const union dvm_value *args, int nargs,
                             union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   /* Focus is what decides where typed text goes, and there is exactly one
    * place it can go: the field the input method is connected to.  A view
    * dropping focus is that connection ending. */
   if (self && self == g_ime_view) {
      luna_ime_hide();
      g_ime_band = 0;
      g_layout_pass_pending = true;
   }
   RETV();
}

/* Runs the listeners a layout pass would have run.  This is the only thing in
 * the emulator that changes the window's shape, so it is the only caller. */
static void ime_run_layout_pass(struct dvm *vm)
{
   for (int i = 0; i < g_nlayout_observers; ++i) {
      dvm_ref listener =
         ui_obj(vm, g_layout_observers[i], "globalLayoutListener",
                "Landroid/view/ViewTreeObserver$OnGlobalLayoutListener;");
      if (!listener) continue;
      struct dvm_class *c = dvm_object_class(vm, listener);
      struct dvm_method *m =
         c ? dvm_find_method(vm, c, "onGlobalLayout", "()V") : NULL;
      if (!m) continue;
      union dvm_value ignored = { 0 };
      if (!dvm_call(vm, m, listener, NULL, 0, &ignored))
         ui_report_exception(vm, "onGlobalLayout");
   }
   /* The same pass delivers the window insets.  There is no status bar,
    * navigation bar or cutout here, so they are zero — a real answer, and the
    * one a full-screen game gets on a gesture-navigation device. */
   for (int i = 0; i < g_ninsets_views; ++i) {
      dvm_ref view = g_insets_views[i];
      dvm_ref listener =
         ui_obj(vm, view, "insetsListener",
                "Landroid/view/View$OnApplyWindowInsetsListener;");
      if (!listener) continue;
      struct dvm_class *c = dvm_object_class(vm, listener);
      struct dvm_method *m = c ? dvm_find_method(
         vm, c, "onApplyWindowInsets",
         "(Landroid/view/View;Landroid/view/WindowInsets;)"
         "Landroid/view/WindowInsets;") : NULL;
      if (!m) continue;
      struct dvm_class *wic =
         dvm__class_by_desc(vm, "Landroid/view/WindowInsets;");
      union dvm_value a[2] = { { .l = view },
                               { .l = wic ? dvm_new_object(vm, wic) : 0 } };
      union dvm_value ignored = { 0 };
      if (!dvm_call(vm, m, listener, a, 2, &ignored))
         ui_report_exception(vm, "onApplyWindowInsets");
   }
}

/* View.requestLayout(): the app asking for a layout pass.  On a device one
 * runs on the next frame and the global-layout listeners fire with it — which
 * is how GameActivity$27 recovers when its field is still off-screen half a
 * second after the keyboard was raised. */
static bool view_request_layout(struct dvm *vm, dvm_ref self,
                                const union dvm_value *args, int nargs,
                                union dvm_value *out)
{
   (void)vm; (void)self; (void)args; (void)nargs; (void)out;
   g_layout_pass_pending = true;
   RETV();
}

/* How many UTF-16 units the Java side would count in this UTF-8 text.  The
 * TextWatcher arguments are char offsets, and a caller that compares them with
 * String.length() gets a different number if these are bytes. */
static int32_t utf16_len(const char *s)
{
   int32_t n = 0;
   for (const unsigned char *p = (const unsigned char *)s; p && *p; ) {
      unsigned c = *p;
      if (c < 0x80u) { ++p; ++n; }
      else if (c < 0xe0u) { p += 2; ++n; }
      else if (c < 0xf0u) { p += 3; ++n; }
      else { p += 4; n += 2; }   /* outside the BMP: a surrogate pair */
   }
   return n;
}

/* Replaces the field's contents and tells its watchers, in the order the
 * platform does: every watcher sees the old text, then the field changes, then
 * every watcher sees the new one.  A watcher that reads getText() in
 * onTextChanged — UE4's does — depends on that ordering. */
static void ime_deliver_text(struct dvm *vm, dvm_ref view, const char *text)
{
   const char *prev = ui_text_of(vm, view);
   dvm_ref old_cs = ui_obj(vm, view, "text", "Ljava/lang/CharSequence;");
   int32_t before = utf16_len(prev ? prev : "");
   int32_t after = utf16_len(text);

   dvm_ref kids = ui_obj(vm, view, "textWatchers", "Ljava/util/List;");
   struct rt_list *l = kids ? list_of(vm, kids) : NULL;

   for (uint32_t i = 0; l && i < l->size; ++i) {
      struct dvm_class *c = dvm_object_class(vm, l->items[i]);
      struct dvm_method *m = c ? dvm_find_method(vm, c, "beforeTextChanged",
         "(Ljava/lang/CharSequence;III)V") : NULL;
      if (!m) continue;
      union dvm_value a[4] = { { .l = old_cs }, { .i = 0 }, { .i = before },
                               { .i = after } }, ignored = { 0 };
      if (!dvm_call(vm, m, l->items[i], a, 4, &ignored))
         ui_report_exception(vm, "beforeTextChanged");
   }

   if (getenv("LUNARIA_IME_TRACE"))
      fprintf(stderr, "[ime] -> view %u: \"%s\" (%d watcher(s))\n",
              (unsigned)view, text, l ? (int)l->size : 0);

   dvm_ref now = dvm_new_string(vm, text);
   union dvm_value v = { .l = now };
   (void)dvm_set_field(vm, view, "text", "Ljava/lang/CharSequence;", v);
   rt_set_int(vm, view, "selectionStart", after);
   rt_set_int(vm, view, "selectionEnd", after);
   ui_invalidate();

   /* The list is re-read: a watcher is allowed to add or drop watchers, and
    * the earlier pointer would be stale if one grew the backing array. */
   kids = ui_obj(vm, view, "textWatchers", "Ljava/util/List;");
   l = kids ? list_of(vm, kids) : NULL;
   for (uint32_t i = 0; l && i < l->size; ++i) {
      struct dvm_class *c = dvm_object_class(vm, l->items[i]);
      struct dvm_method *m = c ? dvm_find_method(vm, c, "onTextChanged",
         "(Ljava/lang/CharSequence;III)V") : NULL;
      if (m) {
         union dvm_value a[4] = { { .l = now }, { .i = 0 }, { .i = before },
                                  { .i = after } }, ignored = { 0 };
         if (!dvm_call(vm, m, l->items[i], a, 4, &ignored))
            ui_report_exception(vm, "onTextChanged");
      }
      kids = ui_obj(vm, view, "textWatchers", "Ljava/util/List;");
      l = kids ? list_of(vm, kids) : NULL;
      if (!l) break;
   }

   kids = ui_obj(vm, view, "textWatchers", "Ljava/util/List;");
   l = kids ? list_of(vm, kids) : NULL;
   for (uint32_t i = 0; l && i < l->size; ++i) {
      struct dvm_class *c = dvm_object_class(vm, l->items[i]);
      struct dvm_method *m = c ? dvm_find_method(vm, c, "afterTextChanged",
         "(Landroid/text/Editable;)V") : NULL;
      if (!m) continue;
      union dvm_value a = { .l = now }, ignored = { 0 };
      if (!dvm_call(vm, m, l->items[i], &a, 1, &ignored))
         ui_report_exception(vm, "afterTextChanged");
   }
}

static void ime_disconnect(struct dvm *vm)
{
   luna_ime_hide();
   g_ime_band = 0;
   g_layout_pass_pending = true;
   if (g_ime_view) {
      dvm_unpin(vm, g_ime_view);
      g_ime_view = 0;
   }
}

/* IME_ACTION_DONE.  It is what a single-line field's Enter reports, and the
 * value GameActivity$36 tests for before it hands the text to native code. */
#define RT_IME_ACTION_DONE 6

static void ime_deliver_action(struct dvm *vm, dvm_ref view)
{
   dvm_ref listener = ui_obj(vm, view, "editorActionListener",
                             "Landroid/widget/TextView$OnEditorActionListener;");
   bool handled = false;
   if (listener) {
      struct dvm_class *c = dvm_object_class(vm, listener);
      struct dvm_method *m = c ? dvm_find_method(vm, c, "onEditorAction",
         "(Landroid/widget/TextView;ILandroid/view/KeyEvent;)Z") : NULL;
      if (m) {
         union dvm_value a[3] = { { .l = view }, { .i = RT_IME_ACTION_DONE },
                                  { .l = 0 } }, ret = { 0 };
         if (dvm_call(vm, m, listener, a, 3, &ret)) handled = ret.i != 0;
         else ui_report_exception(vm, "onEditorAction");
      }
   }
   /* A field that handles the action decides for itself what happens next —
    * UE4's asks for the keyboard to be hidden, which comes back through
    * hideSoftInputFromWindow().  One that does not is finished with the text,
    * and leaving the panel up would be leaving it up for ever. */
   if (!handled) ime_disconnect(vm);
}

static bool imm_show_soft_input(struct dvm *vm, dvm_ref self,
                                const union dvm_value *args, int nargs,
                                union dvm_value *out)
{
   (void)self;
   dvm_ref view = nargs > 0 ? ARG(0).l : 0;
   if (!view) RETI(0);

   if (g_ime_view != view) {
      if (g_ime_view) dvm_unpin(vm, g_ime_view);
      dvm_pin(vm, view);
      g_ime_view = view;
   }

   /* The field is laid out by whatever draws it, and here that is the input
    * method: give the View the geometry the panel gives it, so getHeight()
    * answers what is really on screen rather than the zero of a view no
    * layout pass ever touched. */
   rt_set_int(vm, view, "left", 0);
   rt_set_int(vm, view, "top", 0);
   rt_set_int(vm, view, "right", rt_surface_w());
   rt_set_int(vm, view, "bottom", RT_IME_FIELD_H);

   const char *text = ui_text_of(vm, view);
   int input_type = ui_int(vm, view, "inputType");
   /* setSingleLine(true) and setMaxLines(1) are the two ways a field says it
    * takes one line; either makes Enter the editor action instead of a
    * newline. */
   bool multiline = !ui_int(vm, view, "singleLine") &&
                    ui_int(vm, view, "maxLines") != 1;

   luna_ime_show(text ? text : "", input_type, multiline);
   g_ime_band = luna_ime_band_height(rt_surface_h());
   /* Not fired here: on a device the window resizes and the layout pass runs
    * on the next frame, never inside showSoftInput(), and the caller is
    * holding its own lock while it asks. */
   g_layout_pass_pending = true;
   RETI(1);
}

static bool imm_hide_soft_input(struct dvm *vm, dvm_ref self,
                                const union dvm_value *args, int nargs,
                                union dvm_value *out)
{
   (void)self; (void)args; (void)nargs;
   ime_disconnect(vm);
   RETI(1);
}

static bool imm_is_active(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   (void)vm; (void)self; (void)args; (void)nargs;
   RETI(luna_ime_active() ? 1 : 0);
}

/* Called from the main-looper drain, next to the widget tick, and once per
 * host frame from the pump.  Both are needed: the drain only runs when the
 * guest has just called into Java, and a game waiting for the name the player
 * is typing has no reason to. */
/* LUNARIA_IME_TEST=<seconds>: raise the input method on the app's own text
 * field that long after the guest starts running.  A diagnostic, not a path
 * the guest can take — it goes through exactly the same entry point the app
 * would use, so what it exercises is the real chain. */
static void ime_maybe_self_test(struct dvm *vm)
{
   static int64_t due = -1;
   if (due == -2) return;
   if (due < 0) {
      const char *e = getenv("LUNARIA_IME_TEST");
      long secs = (e && *e) ? atol(e) : 0;
      if (secs <= 0) { due = -2; return; }
      struct timespec ts;
      clock_gettime(CLOCK_MONOTONIC, &ts);
      due = (int64_t)ts.tv_sec + secs;
   }
   struct timespec ts;
   clock_gettime(CLOCK_MONOTONIC, &ts);
   if ((int64_t)ts.tv_sec < due) return;
   if (!g_ime_last_field) return;
   due = -2;

   /* Prefer the app's own entry point.  UE4's is a method on the Activity the
    * field belongs to, and going through it exercises the whole chain the
    * game would take — the posted command, the field being configured, the
    * layout pass, the watchers — rather than only the half below
    * showSoftInput(). */
   dvm_ref ctx = ui_obj(vm, g_ime_last_field, "context",
                        "Landroid/content/Context;");
   struct dvm_class *c = ctx ? dvm_object_class(vm, ctx) : NULL;
   struct dvm_method *m = c ? dvm_find_method(vm, c,
      "AndroidThunkJava_ShowVirtualKeyboardInput",
      "(ILjava/lang/String;Ljava/lang/String;)V") : NULL;
   if (m) {
      fprintf(stderr, "[ime] LUNARIA_IME_TEST: %s.%s\n",
              dvm_class_name(c), m->name);
      union dvm_value a[3] = { { .i = 1 },   /* TYPE_CLASS_TEXT */
                               { .l = dvm_new_string(vm, "Lunaria") },
                               { .l = dvm_new_string(vm, "") } };
      union dvm_value ignored = { 0 };
      if (!dvm_call(vm, m, ctx, a, 3, &ignored))
         ui_report_exception(vm, "AndroidThunkJava_ShowVirtualKeyboardInput");
      return;
   }

   fprintf(stderr, "[ime] LUNARIA_IME_TEST: showSoftInput on view %u\n",
           (unsigned)g_ime_last_field);
   union dvm_value a[2] = { { .l = g_ime_last_field }, { .i = 0 } };
   union dvm_value ignored = { 0 };
   (void)imm_show_soft_input(vm, 0, a, 2, &ignored);
}

static void dvm_ime_tick(struct dvm *vm)
{
   ime_maybe_self_test(vm);
   if (g_layout_pass_pending) {
      g_layout_pass_pending = false;
      ime_run_layout_pass(vm);
   }
   if (!g_ime_view || !luna_ime_active()) return;

   char text[512];
   int events = luna_ime_pump(text, sizeof text);
   if (!events) return;

   dvm_ref view = g_ime_view;
   if (events & LUNA_IME_EV_TEXT) ime_deliver_text(vm, view, text);
   if (events & LUNA_IME_EV_ACCEPT) ime_deliver_action(vm, view);
   else if (events & LUNA_IME_EV_CANCEL) ime_disconnect(vm);
}

void dvm_ime_frame(struct dvm *vm)
{
   if (!g_layout_pass_pending && !g_ime_view) return;
   /* The frame pump does not carry the interpreter lock, and everything below
    * runs guest code. */
   unsigned cookie = dvm_gil_enter_from_guest(vm);
   dvm_ime_tick(vm);
   dvm_gil_leave_to_guest(vm, cookie);
}

/* Called from the pending-queue drain: the emulator's equivalent of the main
 * looper, and so the right thread to run a click callback and to read the view
 * tree while nothing else is mutating it. */
void dvm__ui_tick(struct dvm *vm)
{
   dvm_ime_tick(vm);
   dvm_ref clicks[16];
   int n = 0;
   pthread_mutex_lock(&g_ui_click_lock);
   n = g_ui_nclicks;
   memcpy(clicks, g_ui_clicks, (size_t)n * sizeof clicks[0]);
   g_ui_nclicks = 0;
   pthread_mutex_unlock(&g_ui_click_lock);
   for (int i = 0; i < n; ++i) ui_dispatch_click(vm, clicks[i]);
   if (n) g_ui_dirty = true;
   if (g_ui_dirty) ui_rebuild(vm);
}

static bool adb_init(struct dvm *vm, dvm_ref self,
                     const union dvm_value *args, int nargs,
                     union dvm_value *out)
{
   (void)out;
   union dvm_value v = { .l = nargs > 0 ? ARG(0).l : 0 };
   (void)dvm_set_field(vm, self, "context", "Landroid/content/Context;", v);
   RETV();
}

static bool adb_set_view(struct dvm *vm, dvm_ref self,
                         const union dvm_value *args, int nargs,
                         union dvm_value *out)
{
   union dvm_value v = { .l = nargs > 0 ? ARG(0).l : 0 };
   (void)dvm_set_field(vm, self, "view", "Landroid/view/View;", v);
   RETL(self);
}

static bool adb_set_cancelable(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   union dvm_value v = { .i = nargs > 0 ? ARG(0).i : 1 };
   (void)dvm_set_field(vm, self, "cancelable", "Z", v);
   RETL(self);
}

static bool adb_return_self(struct dvm *vm, dvm_ref self,
                            const union dvm_value *args, int nargs,
                            union dvm_value *out)
{
   (void)vm; (void)args; (void)nargs;
   RETL(self);
}

/* Defined with the Dialog below; Builder.show() is create() plus this. */
static bool dialog_show(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out);

/* AlertDialog.Builder.setTitle / setMessage.
 *
 * These were `adb_return_self`: the chaining worked and the text went nowhere.
 * A dialog is a question, and its text is the question — dropping it leaves
 * the emulator showing a box whose contents nobody, including whoever is
 * reading the log, can find out.  The string forms are kept; the resource-id
 * forms are looked up the same way the rest of the runtime resolves ids. */
static bool adb_set_title(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   (void)nargs;
   union dvm_value v = { .l = ARG(0).l };
   (void)dvm_set_field(vm, self, "title", "Ljava/lang/CharSequence;", v);
   RETL(self);
}

static bool adb_set_message(struct dvm *vm, dvm_ref self,
                            const union dvm_value *args, int nargs,
                            union dvm_value *out)
{
   (void)nargs;
   union dvm_value v = { .l = ARG(0).l };
   (void)dvm_set_field(vm, self, "message", "Ljava/lang/CharSequence;", v);
   RETL(self);
}

/* create() builds the dialog the builder describes.  Everything the builder
 * was told has to travel with it — the cancelable flag decides whether the
 * user may dismiss it, and the text is what it says. */
static bool adb_create(struct dvm *vm, dvm_ref self,
                       const union dvm_value *args, int nargs,
                       union dvm_value *out)
{
   (void)args; (void)nargs;
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/app/AlertDialog;");
   dvm_ref dialog = c ? dvm_new_object(vm, c) : 0;
   if (!dialog) RETL(0);
   union dvm_value v = { .l = self };
   (void)dvm_set_field(vm, dialog, "builder",
                       "Landroid/app/AlertDialog$Builder;", v);
   union dvm_value copy = { 0 };
   (void)dvm_get_field(vm, self, "context", "Landroid/content/Context;", &copy);
   (void)dvm_set_field(vm, dialog, "context", "Landroid/content/Context;", copy);
   /* Builder.setCancelable() defaults to true, and adb_init sets it. */
   copy.i = 0;
   (void)dvm_get_field(vm, self, "cancelable", "Z", &copy);
   (void)dvm_set_field(vm, dialog, "cancelable", "Z", copy);
   (void)dvm_set_field(vm, dialog, "cancelOutside", "Z", copy);
   RETL(dialog);
}

/* Builder.show() is create() *and* show() on Android, and here it is create()
 * alone — the one deliberate deviation in this file.
 *
 * Making it show is a one-line change and it is *not* being made yet, because
 * showing is not the whole of it: the emulator's dialog is a full-screen
 * modal with a dim scrim over the guest's frame, and every pointer event goes
 * to it until one of its buttons is pressed.  Cross Worlds' security module
 * raises one ("Need Security License") behind the title screen, so honouring
 * show() here darkens the title and takes the player's input with it, with
 * nothing on the emulator side that dismisses it.
 *
 * The missing piece is the emulator's own handling of an unanswerable modal,
 * not this call.  Until that exists, the dialog is built and logged (see
 * dialog_show) but not raised, and this comment is the record of the
 * difference — the alternative was leaving it undocumented in a table entry
 * that reads as if show() worked. */
static bool adb_show(struct dvm *vm, dvm_ref self,
                     const union dvm_value *args, int nargs,
                     union dvm_value *out)
{
   union dvm_value dialog = { 0 };
   if (!adb_create(vm, self, args, nargs, &dialog)) return false;
   union dvm_value t = { 0 }, m = { 0 };
   (void)dvm_get_field(vm, self, "title", "Ljava/lang/CharSequence;", &t);
   (void)dvm_get_field(vm, self, "message", "Ljava/lang/CharSequence;", &m);
   const char *ts = t.l ? rt_charseq_utf8(vm, t.l) : NULL;
   const char *ms = m.l ? rt_charseq_utf8(vm, m.l) : NULL;
   if (ts || ms)
      fprintf(stderr, "[dialog] not raised (Builder.show): %s%s%s\n",
              ts ? ts : "", ts && ms ? " — " : "", ms ? ms : "");
   RETL(dialog.l);
}

/* Defined with the rest of the Dialog surface below. */
static bool dialog_ensure_created(struct dvm *vm, dvm_ref self);
static bool dialog_user_cancelable(struct dvm *vm, dvm_ref dialog);

static bool dialog_show(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   /* onCreate() before the listener: the subclass inflates its layout there,
    * and an OnShowListener's first act is usually to look a view up in it. */
   if (!dialog_ensure_created(vm, self)) return false;
   union dvm_value v = { .i = 1 };
   (void)dvm_set_field(vm, self, "showing", "Z", v);
   /* Say what it says.  A modal dialog is where a title stops, and the one
    * thing that explains why is the text on it — which used to exist only as
    * pixels in the overlay, so a headless run or a run that never presented
    * another frame left no record of the question at all. */
   {
      union dvm_value b = { 0 }, t = { 0 }, m = { 0 };
      (void)dvm_get_field(vm, self, "builder",
                          "Landroid/app/AlertDialog$Builder;", &b);
      if (b.l) {
         (void)dvm_get_field(vm, b.l, "title", "Ljava/lang/CharSequence;", &t);
         (void)dvm_get_field(vm, b.l, "message", "Ljava/lang/CharSequence;", &m);
      }
      const char *ts = t.l ? rt_charseq_utf8(vm, t.l) : NULL;
      const char *ms = m.l ? rt_charseq_utf8(vm, m.l) : NULL;
      fprintf(stderr, "[dialog] shown%s%s%s%s%s%s\n",
              ts ? " title=\"" : "", ts ? ts : "", ts ? "\"" : "",
              ms ? " message=\"" : "", ms ? ms : "", ms ? "\"" : "");
      if (!dialog_user_cancelable(vm, self))
         fprintf(stderr, "[dialog]   not cancelable: it has to be answered\n");
   }
   ui_window_shown(vm, self);
   /* A registered OnShowListener runs when the dialog is shown — that is the
    * only moment it ever gets, and apps put their button wiring in it. */
   union dvm_value l = { 0 };
   if (dvm_get_field(vm, self, "showListener",
                     "Landroid/content/DialogInterface$OnShowListener;", &l) &&
       l.l) {
      struct dvm_class *lc = dvm_object_class(vm, l.l);
      struct dvm_method *m =
         lc ? dvm_find_method(vm, lc, "onShow",
                              "(Landroid/content/DialogInterface;)V") : NULL;
      if (m) {
         union dvm_value a = { .l = self }, ignored = { 0 };
         if (!dvm_call(vm, m, l.l, &a, 1, &ignored)) return false;
      }
   }
   RETV();
}

/* Calls one DialogInterface listener, if the dialog carries it. */
static bool dialog_notify(struct dvm *vm, dvm_ref self, const char *field,
                          const char *type, const char *method)
{
   union dvm_value l = { 0 };
   if (!dvm_get_field(vm, self, field, type, &l) || !l.l) return true;
   struct dvm_class *c = dvm_object_class(vm, l.l);
   struct dvm_method *m =
      c ? dvm_find_method(vm, c, method,
                          "(Landroid/content/DialogInterface;)V") : NULL;
   if (!m) return true;
   union dvm_value a = { .l = self }, ignored = { 0 };
   return dvm_call(vm, m, l.l, &a, 1, &ignored);
}

/* Whoever put the dialog up is waiting to be told it came down.  Netmarble's
 * terms flow is exactly that shape: MultipleTermsDialog.dismiss() is how the
 * SDK learns the player answered, and it reports the result to the game from
 * its OnDismissListener.  Dropping the callback left the dialog closed and the
 * game still waiting for an answer it had already been given. */
static bool dialog_dismiss(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   union dvm_value showing = { 0 };
   (void)dvm_get_field(vm, self, "showing", "Z", &showing);
   union dvm_value v = { .i = 0 };
   (void)dvm_set_field(vm, self, "showing", "Z", v);
   ui_window_hidden(vm, self);
   /* dismiss() on a dialog that is not up is a no-op, listeners included. */
   if (!showing.i) RETV();
   /* onStop() before the listener, as the platform orders it: a subclass
    * releases its own state there, and the listener may look at the dialog. */
   struct dvm_class *c = dvm_object_class(vm, self);
   struct dvm_method *stop = c ? dvm_find_method(vm, c, "onStop", "()V") : NULL;
   union dvm_value ignored = { 0 };
   if (stop && !dvm_call(vm, stop, self, NULL, 0, &ignored)) return false;
   return dialog_notify(vm, self, "dismissListener",
                        "Landroid/content/DialogInterface$OnDismissListener;",
                        "onDismiss");
}

/* cancel() is dismiss() preceded by the cancel callback: the two mean
 * different things to the app (the player backed out, versus the dialog
 * finished), and only cancel() reports the first. */
/* Dialog.setCancelable / setCanceledOnTouchOutside.
 *
 * These decide whether the *user* may dismiss the dialog without answering it,
 * and a dialog that says "not cancelable" means it: UE4's MessageBox01 puts
 * one up for a fatal startup condition and expects the player to have to press
 * a button.  Discarding the flags meant the emulator had no way to know which
 * dialogs those are — it could only ever guess, and guessing "dismissable"
 * turns a question the game is waiting on into one it never got an answer to.
 *
 * setCancelable(false) also implies not-cancelable-on-touch-outside, which is
 * what Android does when the two disagree. */
static bool dialog_set_cancelable(struct dvm *vm, dvm_ref self,
                                  const union dvm_value *args, int nargs,
                                  union dvm_value *out)
{
   (void)nargs;
   union dvm_value v = { .i = ARG(0).i != 0 };
   (void)dvm_set_field(vm, self, "cancelable", "Z", v);
   if (!v.i)
      (void)dvm_set_field(vm, self, "cancelOutside", "Z", v);
   RETV();
}

static bool dialog_set_canceled_outside(struct dvm *vm, dvm_ref self,
                                        const union dvm_value *args, int nargs,
                                        union dvm_value *out)
{
   (void)nargs;
   union dvm_value cancelable = { 0 };
   (void)dvm_get_field(vm, self, "cancelable", "Z", &cancelable);
   union dvm_value v = { .i = ARG(0).i != 0 };
   /* setCanceledOnTouchOutside(true) makes the dialog cancelable, as it does
    * on a device. */
   if (v.i && !cancelable.i)
      (void)dvm_set_field(vm, self, "cancelable", "Z", v);
   (void)dvm_set_field(vm, self, "cancelOutside", "Z", v);
   RETV();
}

/* Whether the user may dismiss this dialog without pressing one of its
 * buttons.  Consulted by the emulator's own UI layer, which is the only thing
 * here that can deliver a Back press or a tap outside the dialog. */
static bool dialog_user_cancelable(struct dvm *vm, dvm_ref dialog)
{
   union dvm_value v = { 0 };
   (void)dvm_get_field(vm, dialog, "cancelable", "Z", &v);
   return v.i != 0;
}

static bool dialog_cancel(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   union dvm_value showing = { 0 };
   (void)dvm_get_field(vm, self, "showing", "Z", &showing);
   if (showing.i &&
       !dialog_notify(vm, self, "cancelListener",
                      "Landroid/content/DialogInterface$OnCancelListener;",
                      "onCancel"))
      return false;
   return dialog_dismiss(vm, self, args, nargs, out);
}

static bool dialog_is_showing(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)args; (void)nargs;
   union dvm_value v = { 0 };
   (void)dvm_get_field(vm, self, "showing", "Z", &v);
   RETI(v.i);
}

static const struct rt_field rt_alert_builder_fields[] = {
   { "context", "Landroid/content/Context;" },
   { "view", "Landroid/view/View;" },
   { "cancelable", "Z" },
   { "title", "Ljava/lang/CharSequence;" },
   { "message", "Ljava/lang/CharSequence;" },
   F_END,
};

static const struct rt_method rt_alert_builder[] = {
   M("<init>", "(Landroid/content/Context;)V", adb_init),
   M("<init>", "(Landroid/content/Context;I)V", adb_init),
   M("setView", "(Landroid/view/View;)Landroid/app/AlertDialog$Builder;",
     adb_set_view),
   /* The resource-id forms carry an id this runtime has no string table for;
    * the text forms are the ones that arrive with their content. */
   M("setTitle", "(I)Landroid/app/AlertDialog$Builder;", adb_return_self),
   M("setTitle", "(Ljava/lang/CharSequence;)Landroid/app/AlertDialog$Builder;",
     adb_set_title),
   M("setMessage", "(I)Landroid/app/AlertDialog$Builder;", adb_return_self),
   M("setMessage",
     "(Ljava/lang/CharSequence;)Landroid/app/AlertDialog$Builder;",
     adb_set_message),
   M("setPositiveButton",
     "(ILandroid/content/DialogInterface$OnClickListener;)Landroid/app/AlertDialog$Builder;",
     adb_return_self),
   M("setPositiveButton",
     "(Ljava/lang/CharSequence;Landroid/content/DialogInterface$OnClickListener;)Landroid/app/AlertDialog$Builder;",
     adb_return_self),
   M("setNegativeButton",
     "(ILandroid/content/DialogInterface$OnClickListener;)Landroid/app/AlertDialog$Builder;",
     adb_return_self),
   M("setNeutralButton",
     "(ILandroid/content/DialogInterface$OnClickListener;)Landroid/app/AlertDialog$Builder;",
     adb_return_self),
   M("setCancelable", "(Z)Landroid/app/AlertDialog$Builder;",
     adb_set_cancelable),
   M("create", "()Landroid/app/AlertDialog;", adb_create),
   M("show", "()Landroid/app/AlertDialog;", adb_show),
   M_END,
};

/* android.widget.Toast — the transient message the system shows over whatever
 * is on screen.
 *
 * makeText() was unresolved, so it answered 0 and the `show()` on the very
 * next line threw NullPointerException on a null receiver.  On a device
 * makeText always hands an object back, so no caller guards against that: in
 * this title the toast is raised from ConfigCenter.loadConfig()'s error path
 * and the NPE took Application.onCreate() down with it, leaving the whole
 * Combo SDK uninitialised for the rest of the run.
 *
 * The object and its state are what callers depend on, so they are real here.
 * The message goes to the emulator log next to [dialog]: a toast is not modal
 * and disappears on its own, and the overlay has one document, which a modal
 * dialog owns — drawing one there would take the touches the game needs. */
