/* dvm.c owns class_register(); the runtime reaches it through this shim so the
 * registry stays in one place. */
struct dvm_class *dvm__register_builtin(struct dvm *vm, const char *desc);

struct dvm_class *dvm_runtime_define(struct dvm *vm, const char *desc)
{
   const struct rt_class *rc = NULL;
   for (size_t i = 0; i < sizeof rt_classes / sizeof rt_classes[0]; ++i)
      if (!strcmp(rt_classes[i].desc, desc)) { rc = &rt_classes[i]; break; }
   if (!rc) return NULL;

   struct dvm_class *c = dvm__register_builtin(vm, desc);
   if (!c) return NULL;
   c->init_state = 2;   /* nothing to run: the tables are already populated */
   c->is_interface = rc->is_interface;
   if (c->is_interface) c->access |= DEX_ACC_INTERFACE | DEX_ACC_ABSTRACT;
   c->runtime_signature = rc->generic_signature;

   /* Registered before resolving the super so a cycle cannot recurse. */
   if (rc->super) c->super = dvm__class_by_desc(vm, rc->super);

   if (rc->ifaces) {
      int ni = 0;
      while (rc->ifaces[ni]) ++ni;
      c->ifaces = calloc((size_t)ni, sizeof *c->ifaces);
      if (c->ifaces) {
         c->nifaces = ni;
         for (int i = 0; i < ni; ++i)
            c->ifaces[i] = dvm__class_by_desc(vm, rc->ifaces[i]);
      }
   }

   int nsf = 0;
   if (rc->sfields) while (rc->sfields[nsf].name) ++nsf;
   c->nsfields = nsf;
   c->nsslots  = nsf;
   if (nsf) {
      c->sfields = calloc((size_t)nsf, sizeof *c->sfields);
      c->sslots  = calloc((size_t)nsf, sizeof *c->sslots);
      for (int i = 0; i < nsf && c->sfields && c->sslots; ++i) {
         c->sfields[i].cls   = c;
         c->sfields[i].name  = rc->sfields[i].name;
         c->sfields[i].type  = rc->sfields[i].type;
         c->sfields[i].kind  = dvm__kind_of(rc->sfields[i].type);
         c->sfields[i].width = 1;
         c->sfields[i].slot  = (uint16_t)i;
         c->sfields[i].access = DEX_ACC_STATIC;
      }
   }

   int nf = 0;
   if (rc->fields) while (rc->fields[nf].name) ++nf;
   c->nifields = nf;
   if (nf) {
      c->ifields = calloc((size_t)nf, sizeof *c->ifields);
      int base = c->super ? c->super->islots : 0;
      for (int i = 0; i < nf && c->ifields; ++i) {
         c->ifields[i].cls = c;
         c->ifields[i].name = rc->fields[i].name;
         c->ifields[i].type = rc->fields[i].type;
         c->ifields[i].kind = dvm__kind_of(rc->fields[i].type);
         c->ifields[i].width = 1;
         c->ifields[i].slot = (uint16_t)(base + i);
      }
      c->islots = base + nf;
   } else {
      c->islots = c->super ? c->super->islots : 0;
   }

   int nm = 0;
   if (rc->methods) while (rc->methods[nm].name) ++nm;
   c->nmethods = nm;
   if (nm) {
      c->methods = calloc((size_t)nm, sizeof *c->methods);
      for (int i = 0; i < nm && c->methods; ++i) {
         struct dvm_method *m = &c->methods[i];
         m->cls = c;
         m->name = rc->methods[i].name;
         m->sig = strdup(rc->methods[i].sig);
         m->access = rc->methods[i].access;
         m->builtin = rc->methods[i].fn;
         m->arg_slots = dvm_sig_arg_slots(m->sig);
         m->arg_count = dvm_sig_arg_count(m->sig);
         m->ret_kind = dvm_sig_return_kind(m->sig);
      }
   }

   /* Static int constants, for the classes that expose their field numbers or
    * enum-like values to bytecode through sget. */
   int nc = 0;
   for (size_t i = 0; i < sizeof rt_consts / sizeof rt_consts[0]; ++i)
      if (!strcmp(rt_consts[i].cls, desc)) ++nc;
   if (nc) {
      c->sfields = calloc((size_t)nc, sizeof *c->sfields);
      c->sslots = calloc((size_t)nc, sizeof *c->sslots);
      if (c->sfields && c->sslots) {
         c->nsfields = nc;
         c->nsslots = nc;
         int k = 0;
         for (size_t i = 0; i < sizeof rt_consts / sizeof rt_consts[0]; ++i) {
            if (strcmp(rt_consts[i].cls, desc)) continue;
            c->sfields[k].cls = c;
            c->sfields[k].name = rt_consts[i].name;
            c->sfields[k].type = "I";
            c->sfields[k].kind = 'I';
            c->sfields[k].width = 1;
            c->sfields[k].access = DEX_ACC_STATIC;
            c->sfields[k].slot = (uint16_t)k;
            c->sslots[k].i = rt_consts[i].value;
            ++k;
         }
      }
   }

   /* <Box>.TYPE is the primitive Class, and it is what reflective code passes
    * to getMethod() to name an `int` parameter.  Without it that entry was
    * null and every overload looked alike. */
   {
      static const struct { const char *box, *prim; } prims[] = {
         { "Ljava/lang/Integer;", "I" },
         { "Ljava/lang/Long;", "J" },
         { "Ljava/lang/Short;", "S" },
         { "Ljava/lang/Byte;", "B" },
         { "Ljava/lang/Character;", "C" },
         { "Ljava/lang/Boolean;", "Z" },
         { "Ljava/lang/Float;", "F" },
         { "Ljava/lang/Double;", "D" },
         { "Ljava/lang/Void;", "V" },
      };
      for (size_t i = 0; i < sizeof prims / sizeof prims[0]; ++i) {
         if (strcmp(desc, prims[i].box)) continue;
         int k = c->nsfields;
         struct dvm_field *sf = realloc(c->sfields, (size_t)(k + 1) * sizeof *sf);
         union dvm_value *sv = realloc(c->sslots, (size_t)(k + 1) * sizeof *sv);
         if (sf) c->sfields = sf;
         if (sv) c->sslots = sv;
         if (!sf || !sv) break;
         memset(&c->sfields[k], 0, sizeof c->sfields[k]);
         memset(&c->sslots[k], 0, sizeof c->sslots[k]);
         c->sfields[k].cls = c;
         c->sfields[k].name = "TYPE";
         c->sfields[k].type = "Ljava/lang/Class;";
         c->sfields[k].kind = 'L';
         c->sfields[k].width = 1;
         c->sfields[k].access = DEX_ACC_STATIC;
         c->sfields[k].slot = (uint16_t)k;
         c->sslots[k].l =
            class_object_for(vm, dvm__class_by_desc(vm, prims[i].prim));
         c->nsfields = k + 1;
         c->nsslots = k + 1;
         break;
      }
   }

   /* EGL14's EGL_NO_* are objects, not ints: they are what a caller compares
    * a display or context against to ask "did that fail?".  A null there would
    * make every such comparison say "yes" for a display that works. */
   if (!strcmp(desc, "Landroid/opengl/EGL14;")) {
      static const struct { const char *name, *type; } sentinels[] = {
         { "EGL_NO_DISPLAY", EGL_D_DISPLAY },
         { "EGL_NO_CONTEXT", EGL_D_CONTEXT },
         { "EGL_NO_SURFACE", EGL_D_SURFACE },
      };
      int extra = (int)(sizeof sentinels / sizeof sentinels[0]);
      struct dvm_field *sf = realloc(c->sfields,
                                     (size_t)(nc + extra) * sizeof *sf);
      union dvm_value *sv = realloc(c->sslots,
                                    (size_t)(nc + extra) * sizeof *sv);
      if (sf) c->sfields = sf;
      if (sv) c->sslots = sv;
      if (sf && sv) {
         for (int i = 0; i < extra; ++i) {
            int k = nc + i;
            memset(&c->sfields[k], 0, sizeof c->sfields[k]);
            c->sfields[k].cls = c;
            c->sfields[k].name = sentinels[i].name;
            c->sfields[k].type = sentinels[i].type;
            c->sfields[k].kind = 'L';
            c->sfields[k].width = 1;
            c->sfields[k].access = DEX_ACC_STATIC;
            c->sfields[k].slot = (uint16_t)k;
            c->sslots[k].l = egl_obj(vm, sentinels[i].type, 0u);
         }
         c->nsfields = nc + extra;
         c->nsslots = nc + extra;
      }
   }

   /* JSONObject.NULL is a static sentinel, not an instance field. */
   if (!strcmp(desc, "Lorg/json/JSONObject;")) {
      c->nsfields = nf;
      c->sfields = c->ifields;
      c->ifields = NULL;
      c->nifields = 0;
      c->islots = c->super ? c->super->islots : 0;
      for (int i = 0; i < c->nsfields; ++i) c->sfields[i].slot = (uint16_t)i;
      c->nsslots = c->nsfields;
      c->sslots = calloc((size_t)(c->nsslots ? c->nsslots : 1),
                         sizeof *c->sslots);
   }

   /* Boolean.TRUE/FALSE are canonical, eagerly-created objects.  Builtin
    * classes have no dex <clinit>, so leaving these static fields implicit
    * makes every Kotlin boolean box become null. */
   if (!strcmp(desc, "Ljava/lang/Boolean;")) {
      static const char *const names[] = { "FALSE", "TRUE" };
      int base = c->nsfields;
      struct dvm_field *sf = realloc(c->sfields,
                                     (size_t)(base + 2) * sizeof *sf);
      union dvm_value *sv = realloc(c->sslots,
                                    (size_t)(base + 2) * sizeof *sv);
      if (sf) c->sfields = sf;
      if (sv) c->sslots = sv;
      if (sf && sv) {
         for (int i = 0; i < 2; ++i) {
            int k = base + i;
            memset(&c->sfields[k], 0, sizeof c->sfields[k]);
            memset(&c->sslots[k], 0, sizeof c->sslots[k]);
            c->sfields[k].cls = c;
            c->sfields[k].name = names[i];
            c->sfields[k].type = "Ljava/lang/Boolean;";
            c->sfields[k].kind = 'L';
            c->sfields[k].width = 1;
            c->sfields[k].access = DEX_ACC_STATIC;
            c->sfields[k].slot = (uint16_t)k;
            dvm_ref value = dvm_new_object(vm, c);
            struct dvm_object *o = dvm__obj(vm, value);
            if (o && o->slots) o->slots[0].i = i;
            c->sslots[k].l = value;
            if (value) dvm_pin(vm, value);
         }
         c->nsfields = c->nsslots = base + 2;
      }
   }

   if (!strcmp(desc, "Ljava/util/Collections;")) {
      static const char *const types[] = {
         "Ljava/util/ArrayList;", "Ljava/util/HashSet;", "Ljava/util/HashMap;"
      };
      c->nsfields = nf;
      c->sfields = c->ifields;
      c->ifields = NULL;
      c->nifields = 0;
      c->islots = c->super ? c->super->islots : 0;
      c->nsslots = nf;
      c->sslots = calloc((size_t)nf, sizeof *c->sslots);
      for (int i = 0; i < nf; ++i) {
         c->sfields[i].slot = (uint16_t)i;
         c->sfields[i].access = DEX_ACC_STATIC;
         struct dvm_class *vc = dvm__class_by_desc(vm, types[i]);
         dvm_ref value = vc ? dvm_new_object(vm, vc) : 0;
         union dvm_value ignored = { 0 };
         if (i < 2) (void)list_init(vm, value, NULL, 0, &ignored);
         else (void)map_init(vm, value, NULL, 0, &ignored);
         c->sslots[i].l = value;
         if (value) dvm_pin(vm, value);
      }
   }

   /* System.out / System.err need real objects to receive println(). */
   if (!strcmp(desc, "Ljava/lang/System;")) {
      c->nsfields = nf;
      c->sfields = c->ifields;
      c->ifields = NULL;
      c->nifields = 0;
      c->islots = c->super ? c->super->islots : 0;
      for (int i = 0; i < c->nsfields; ++i) c->sfields[i].slot = (uint16_t)i;
      c->nsslots = c->nsfields;
      c->sslots = calloc((size_t)(c->nsslots ? c->nsslots : 1), sizeof *c->sslots);
      struct dvm_class *ps = dvm__class_by_desc(vm, "Ljava/io/PrintStream;");
      for (int i = 0; i < c->nsslots; ++i)
         c->sslots[i].l = dvm_new_object(vm, ps);
   }

   /* AsyncTask creates its process-wide pool in the framework class
    * initializer.  Builtin classes do not execute dex <clinit>, so materialize
    * the same non-null Executor static here. */
   if (!strcmp(desc, "Landroid/os/AsyncTask;")) {
      c->nsfields = nf;
      c->sfields = c->ifields;
      c->ifields = NULL;
      c->nifields = 0;
      c->islots = c->super ? c->super->islots : 0;
      for (int i = 0; i < c->nsfields; ++i) {
         c->sfields[i].slot = (uint16_t)i;
         c->sfields[i].access = DEX_ACC_STATIC;
      }
      c->nsslots = c->nsfields;
      c->sslots = calloc((size_t)(c->nsslots ? c->nsslots : 1),
                         sizeof *c->sslots);
      struct dvm_class *ec =
         dvm__class_by_desc(vm, "Ljava/util/concurrent/ThreadPoolExecutor;");
      if (c->sslots && c->nsslots > 0 && ec) {
         c->sslots[0].l = dvm_new_object(vm, ec);
         dvm_pin(vm, c->sslots[0].l);
      }
   }

   /* Locale's constants are static fields holding instances, created by its
    * own <clinit> on a real runtime. */
   if (!strcmp(desc, "Ljava/util/Locale;")) {
      static const struct { const char *name, *lang, *country; } locs[] = {
         { "ROOT", "", "" },        { "ENGLISH", "en", "" },
         { "US", "en", "US" },      { "UK", "en", "GB" },
         { "CANADA", "en", "CA" },  { "KOREAN", "ko", "" },
         { "KOREA", "ko", "KR" },   { "JAPANESE", "ja", "" },
         { "JAPAN", "ja", "JP" },   { "CHINESE", "zh", "" },
         { "CHINA", "zh", "CN" },   { "PRC", "zh", "CN" },
         { "TAIWAN", "zh", "TW" },  { "SIMPLIFIED_CHINESE", "zh", "CN" },
         { "TRADITIONAL_CHINESE", "zh", "TW" },
         { "FRENCH", "fr", "" },    { "FRANCE", "fr", "FR" },
         { "GERMAN", "de", "" },    { "GERMANY", "de", "DE" },
         { "ITALIAN", "it", "" },   { "ITALY", "it", "IT" },
      };
      int n = (int)(sizeof locs / sizeof locs[0]);
      c->sfields = calloc((size_t)n, sizeof *c->sfields);
      c->sslots = calloc((size_t)n, sizeof *c->sslots);
      if (c->sfields && c->sslots) {
         c->nsfields = n;
         c->nsslots = n;
         for (int i = 0; i < n; ++i) {
            c->sfields[i].cls = c;
            c->sfields[i].name = locs[i].name;
            c->sfields[i].type = desc;
            c->sfields[i].kind = 'L';
            c->sfields[i].width = 1;
            c->sfields[i].slot = (uint16_t)i;
            dvm_ref o = dvm_new_object(vm, c);
            union dvm_value v = { 0 };
            v.l = dvm_new_string(vm, locs[i].lang);
            (void)dvm_set_field(vm, o, "language", "Ljava/lang/String;", v);
            v.l = dvm_new_string(vm, locs[i].country);
            (void)dvm_set_field(vm, o, "country", "Ljava/lang/String;", v);
            dvm_pin(vm, o);
            c->sslots[i].l = o;
         }
      }
   }

   /* StandardCharsets exposes its charsets as static fields, and Kotlin's
    * string helpers null-check them on the way in. */
   if (!strcmp(desc, "Ljava/nio/charset/StandardCharsets;")) {
      static const char *const names[] = {
         "UTF_8", "US_ASCII", "ISO_8859_1", "UTF_16", "UTF_16BE", "UTF_16LE",
      };
      static const char *const ids[] = {
         "UTF-8", "US-ASCII", "ISO-8859-1", "UTF-16", "UTF-16BE", "UTF-16LE",
      };
      int n = (int)(sizeof names / sizeof names[0]);
      struct dvm_class *cc =
         dvm__class_by_desc(vm, "Ljava/nio/charset/Charset;");
      c->sfields = calloc((size_t)n, sizeof *c->sfields);
      c->sslots = calloc((size_t)n, sizeof *c->sslots);
      if (c->sfields && c->sslots && cc) {
         c->nsfields = n;
         c->nsslots = n;
         for (int i = 0; i < n; ++i) {
            c->sfields[i].cls = c;
            c->sfields[i].name = names[i];
            c->sfields[i].type = "Ljava/nio/charset/Charset;";
            c->sfields[i].kind = 'L';
            c->sfields[i].width = 1;
            c->sfields[i].access = DEX_ACC_STATIC;
            c->sfields[i].slot = (uint16_t)i;
            dvm_ref o = dvm_new_object(vm, cc);
            union dvm_value v = { .l = dvm_new_string(vm, ids[i]) };
            (void)dvm_set_field(vm, o, "name", "Ljava/lang/String;", v);
            dvm_pin(vm, o);
            c->sslots[i].l = o;
         }
      }
   }

   /* TimeUnit's constants are static fields holding instances of the enum;
    * javac emits them from <clinit>, which a builtin class never runs. */
   if (!strcmp(desc, "Ljava/util/concurrent/TimeUnit;")) {
      static const struct { const char *name; int64_t nanos; } units[] = {
         { "NANOSECONDS",   1LL },
         { "MICROSECONDS",  1000LL },
         { "MILLISECONDS",  1000000LL },
         { "SECONDS",       1000000000LL },
         { "MINUTES",       60LL * 1000000000LL },
         { "HOURS",         3600LL * 1000000000LL },
         { "DAYS",          86400LL * 1000000000LL },
      };
      int n = (int)(sizeof units / sizeof units[0]);
      c->sfields = calloc((size_t)n, sizeof *c->sfields);
      c->sslots = calloc((size_t)n, sizeof *c->sslots);
      if (c->sfields && c->sslots) {
         c->nsfields = n;
         c->nsslots = n;
         for (int i = 0; i < n; ++i) {
            c->sfields[i].cls = c;
            c->sfields[i].name = units[i].name;
            c->sfields[i].type = desc;
            c->sfields[i].kind = 'L';
            c->sfields[i].width = 1;
            c->sfields[i].slot = (uint16_t)i;

            dvm_ref u = dvm_new_object(vm, c);
            union dvm_value v = { 0 };
            v.j = units[i].nanos;
            (void)dvm_set_field(vm, u, "nanos", "J", v);
            v.l = dvm_new_string(vm, units[i].name);
            (void)dvm_set_field(vm, u, "name", "Ljava/lang/String;", v);
            v.i = i;
            (void)dvm_set_field(vm, u, "ordinal", "I", v);
            dvm_pin(vm, u);
            c->sslots[i].l = u;
         }
      }
   }

   /* ZoneOffset.UTC and the ISO DateTimeFormatter constants: both are read
    * with sget, and both are created by a <clinit> a builtin class never runs.
    * The formatters are the patterns java.time defines for them — the
    * renderer behind format() is the SimpleDateFormat one. */
   if (!strcmp(desc, "Ljava/time/ZoneOffset;") ||
       !strcmp(desc, "Ljava/time/format/DateTimeFormatter;")) {
      static const char *const zone_names[] = { "UTC", "MIN", "MAX" };
      static const int32_t zone_seconds[] = { 0, -18 * 3600, 18 * 3600 };
      static const char *const fmt_names[] = {
         "ISO_LOCAL_DATE", "ISO_LOCAL_TIME", "ISO_LOCAL_DATE_TIME",
         "ISO_OFFSET_DATE_TIME", "ISO_INSTANT",
      };
      static const char *const fmt_patterns[] = {
         "yyyy-MM-dd", "HH:mm:ss", "yyyy-MM-dd'T'HH:mm:ss",
         "yyyy-MM-dd'T'HH:mm:ssXXX", "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",
      };
      bool is_zone = !strcmp(desc, "Ljava/time/ZoneOffset;");
      int n = is_zone ? (int)(sizeof zone_names / sizeof zone_names[0])
                      : (int)(sizeof fmt_names / sizeof fmt_names[0]);
      c->sfields = calloc((size_t)n, sizeof *c->sfields);
      c->sslots = calloc((size_t)n, sizeof *c->sslots);
      if (c->sfields && c->sslots) {
         c->nsfields = n;
         c->nsslots = n;
         for (int i = 0; i < n; ++i) {
            c->sfields[i].cls = c;
            c->sfields[i].name = is_zone ? zone_names[i] : fmt_names[i];
            c->sfields[i].type = desc;
            c->sfields[i].kind = 'L';
            c->sfields[i].width = 1;
            c->sfields[i].access = DEX_ACC_STATIC;
            c->sfields[i].slot = (uint16_t)i;
            dvm_ref o = dvm_new_object(vm, c);
            union dvm_value v = { 0 };
            if (is_zone) {
               v.i = zone_seconds[i];
               (void)dvm_set_field(vm, o, "seconds", "I", v);
            } else {
               v.l = dvm_new_string(vm, fmt_patterns[i]);
               (void)dvm_set_field(vm, o, "pattern", "Ljava/lang/String;", v);
            }
            dvm_pin(vm, o);
            c->sslots[i].l = o;
         }
      }
   }

   return c;
}

void dvm_runtime_install(struct dvm *vm)
{
   /* Object first: everything else names it as its super. */
   (void)dvm__class_by_desc(vm, "Ljava/lang/Object;");
   (void)dvm__class_by_desc(vm, "Ljava/lang/String;");
   (void)dvm__class_by_desc(vm, "Ljava/lang/Class;");
   (void)dvm__class_by_desc(vm, "Ljava/lang/Throwable;");
}
